package com.revalclan;

import com.revalclan.collectionlog.CollectionLogManager;
import com.revalclan.combatachievements.CombatAchievementManager;
import com.revalclan.diaries.AchievementDiaryManager;
import com.revalclan.pbs.ClogPersonalBestCapture;
import com.revalclan.pbs.PersonalBestManager;
import com.revalclan.player.PlayerManager;
import com.revalclan.quests.QuestManager;
import com.revalclan.util.SyncStateManager;
import com.revalclan.util.Worlds;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarClientID;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;

/**
 * Collects ALL player data by coordinating various managers
 */
@Slf4j
@Singleton
public class PlayerDataCollector {
	@Inject
	private Client client;

	@Inject
	private PlayerManager playerManager;

	@Inject
	private QuestManager questManager;

	@Inject
	private AchievementDiaryManager achievementDiaryManager;

	@Inject
	private CombatAchievementManager combatAchievementManager;

	@Inject
	private CollectionLogManager collectionLogManager;

	@Inject
	private PersonalBestManager personalBestManager;

	@Inject
	private ClogPersonalBestCapture clogPersonalBestCapture;

	@Inject
	private SyncStateManager syncStateManager;

	/**
	 * Full payload for SYNC — the only path that carries the collection log.
	 */
	public Map<String, Object> collectSyncData() {
		Map<String, Object> data = collectFullState();
		data.put("collectionLog", collectionLogManager.sync());
		attachFingerprint(data);
		return data;
	}

	/**
	 * LOGIN/LOGOUT payload: slim (player + fingerprint) when unchanged since
	 * the last acked fingerprint, full otherwise. Never carries the collection
	 * log — no real scan exists at boundaries.
	 */
	public Map<String, Object> collectBoundaryData() {
		Map<String, Object> data = collectFullState();

		String fingerprint = attachFingerprint(data);
		if (fingerprint != null) {
			String acked = syncStateManager.getAckedFingerprint(client.getAccountHash());
			if (fingerprint.equals(acked)) {
				Map<String, Object> slim = new HashMap<>();
				slim.put("player", data.get("player"));
				slim.put("syncFingerprint", fingerprint);
				data = slim;
			}
		}

		// Jagex's own "Time played" (minutes): a server snapshot the client receives at
		// every login/hop, independent of the summary tab's display toggle. The backend
		// reads it on LOGIN as calibration for the sessions it stores.
		int playtime = client.getVarcIntValue(VarClientID.ACCOUNT_SUMMARY_PLAYTIME);
		if (playtime > 0) data.put("playtimeMinutes", playtime);

		return data;
	}

	private Map<String, Object> collectFullState() {
		Map<String, Object> data = new HashMap<>();
		data.put("player", playerManager.sync());
		data.put("quests", questManager.sync());
		data.put("achievementDiaries", achievementDiaryManager.sync());
		data.put("combatAchievements", combatAchievementManager.sync());
		data.put("personalBests", personalBestManager.sync());
		data.put("clogPersonalBests", clogPersonalBestCapture.sync());
		return data;
	}

	/**
	 * Attach the state fingerprint (null when skipped). Seasonal worlds are
	 * skipped — leagues state is a different character.
	 */
	private String attachFingerprint(Map<String, Object> data) {
		if (Worlds.isSeasonal(client)) return null;
		String fingerprint = syncStateManager.computeFingerprint(data);
		if (fingerprint != null) {
			data.put("syncFingerprint", fingerprint);
		}
		return fingerprint;
	}
}

package com.revalclan;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

/**
 * Which game events get tracked and sent to Reval is decided by the backend
 * (see FilterManager), not by the player. The only per-player switches left
 * here are the ones that change what the player themself sees or shares.
 */
@ConfigGroup("revalclan")
public interface RevalClanConfig extends Config {

	// ── Panel Settings ─────────────────────────────────────────────────
	@ConfigSection(
		name = "Panel Settings",
		description = "Customize the Reval side panel appearance",
		position = 0
	)
	String panelSection = "panelSection";

	@ConfigItem(
		keyName = "hideCompletedItems",
		name = "Hide completed items",
		description = "Only show incomplete milestones, combat achievements and collection log tiers on the profile",
		section = panelSection,
		position = 0
	)
	default boolean hideCompletedItems() {
		return false;
	}

	// ── Profile cards ──────────────────────────────────────────────────
	@ConfigSection(
		name = "Profile cards",
		description = "Where the 'View Reval Profile' right-click option appears",
		position = 1
	)
	String profileCardsSection = "profileCardsSection";

	@ConfigItem(
		keyName = "profileCardsOnPlayers",
		name = "Players",
		description = "View Reval Profile when right-clicking a clan member in the world (off by default to keep the menu short)",
		section = profileCardsSection,
		position = 0
	)
	default boolean profileCardsOnPlayers() {
		return false;
	}

	@ConfigItem(
		keyName = "profileCardsInChat",
		name = "Chat",
		description = "View Reval Profile when right-clicking a clan member's name in chat",
		section = profileCardsSection,
		position = 1
	)
	default boolean profileCardsInChat() {
		return true;
	}

	@ConfigItem(
		keyName = "profileCardsInClanList",
		name = "Clan list",
		description = "View Reval Profile when right-clicking a member in the clan member list",
		section = profileCardsSection,
		position = 2
	)
	default boolean profileCardsInClanList() {
		return true;
	}

	// ── Events ─────────────────────────────────────────────────────────
	@ConfigSection(
		name = "Events",
		description = "Clan event features",
		position = 2
	)
	String clanEventsSection = "clanEventsSection";

	/**
	 * Keeps the old "teamNameColors" key on purpose: this used to be the single
	 * toggle for both surfaces, so anyone who had already switched colors off
	 * stays switched off for the clan list instead of having them reappear.
	 */
	@ConfigItem(
		keyName = "teamNameColors",
		name = "Team colors: clan list",
		description = "Color clan members' names by their event team in the clan member list",
		section = clanEventsSection,
		position = 0
	)
	default boolean teamColorsInClanList() {
		return true;
	}

	@ConfigItem(
		keyName = "teamColorsInChat",
		name = "Team colors: chat",
		description = "Color clan members' names by their event team in clan chat (off by default - chat is busy enough)",
		section = clanEventsSection,
		position = 1
	)
	default boolean teamColorsInChat() {
		return false;
	}

	// ── Notifications ──────────────────────────────────────────────────
	@ConfigSection(
		name = "Notifications",
		description = "What the plugin shows you and what it shares with the clan",
		position = 3
	)
	String eventsSection = "eventsSection";

	@ConfigItem(
		keyName = "showAnnouncements",
		name = "Show clan notifications",
		description = "Show Reval announcements and notifications in chat",
		section = eventsSection,
		position = 0
	)
	default boolean showAnnouncements() {
		return true;
	}

	@ConfigItem(
		keyName = "notifyDeath",
		name = "Send player deaths to Discord",
		description = "Post your deaths (and who killed you) to the clan Discord",
		section = eventsSection,
		position = 1
	)
	default boolean notifyDeath() {
		return true;
	}

	@ConfigItem(
		keyName = "notifyLeagues",
		name = "Leagues Events",
		description = "Track Leagues events (tasks, relics, areas, combat masteries)",
		section = eventsSection,
		position = 2
	)
	default boolean notifyLeagues() {
		return true;
	}
}

package com.revalclan;

