package com.revalclan.api.common;

/** What the HTTP layer needs from any response envelope, plugin or public. */
public interface ApiEnvelope {
	boolean isSuccess();

	/** Human-readable failure reason, or null when the envelope carries none. */
	String getErrorMessage();
}

package com.revalclan.api.common;

import lombok.Data;

/**
 * Base API response wrapper used by all plugin API endpoints
 */
@Data
public abstract class ApiResponse implements ApiEnvelope {
    private String status;
    private String message;

    @Override
    public boolean isSuccess() {
        return "success".equals(status);
    }

    @Override
    public String getErrorMessage() {
        return message;
    }

    public boolean isError() {
        return "error".equals(status);
    }
}

package com.revalclan.api.common;

import lombok.Data;

/**
 * Envelope of the public (no-auth) API the homepage reads:
 * {"success": true, "data": ...} on success, {"success": false, "error": "..."} on failure.
 */
@Data
public abstract class PublicApiResponse implements ApiEnvelope {
	private Boolean success;
	private String error;

	@Override
	public boolean isSuccess() {
		return Boolean.TRUE.equals(success);
	}

	@Override
	public String getErrorMessage() {
		return error;
	}
}

