	public Map<String, Object> sync() {
		Map<String, Object> diaryData = new HashMap<>();
		Map<String, Map<String, Boolean>> diaryProgress = new HashMap<>();

		int totalCompleted = 0;

		for (Map.Entry<String, Map<String, Integer>> regionEntry : diaryVarbits.entrySet()) {
			String region = regionEntry.getKey();
			Map<String, Boolean> tierProgress = new HashMap<>();

			for (Map.Entry<String, Integer> tierEntry : regionEntry.getValue().entrySet()) {
				String tier = tierEntry.getKey();
				int varbitId = tierEntry.getValue();
				int value = client.getVarbitValue(varbitId);

				// Karamja Easy (3578), Medium (3599), Hard (3611) special case
				// 0 = not started, 1 = started, 2 = completed
				boolean isComplete;
				if (varbitId == 3578 || varbitId == 3599 || varbitId == 3611) {
					isComplete = value > 1;
				} else {
					isComplete = value > 0;
				}

				tierProgress.put(tier, isComplete);

				if (isComplete) {
					totalCompleted++;
				}
			}

			diaryProgress.put(region, tierProgress);
		}

		diaryData.put("progress", diaryProgress);
		diaryData.put("totalCompleted", totalCompleted);
		diaryData.put("totalDiaries", 48); // 12 regions * 4 tiers

		return diaryData;
	}
}

package com.revalclan.events;

import com.revalclan.api.RevalApiService;
import com.revalclan.api.events.EventsResponse;
import com.revalclan.util.ClanRanks;
import net.runelite.api.Client;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;

/**
 * Admin-only: tracks which clan members have registered for an upcoming
 * event. {@link RegistrationMarksOverlay} draws a checkmark after their name
 * in the clan sidepanel and shows the event(s) on hover. Uses only the last
 * explicitly fetched event list; startup/login/redraw never request it.
 */
@Singleton
public class RegistrationMarks {
	private final Client client;

	/** Standardized nickname -> comma-joined upcoming event names */
	private volatile Map<String, String> registrations = Map.of();

	@Inject
	public RegistrationMarks(Client client, RevalApiService apiService) {
		this.client = client;
		apiService.addEventsListener(this::update);
	}


	Map<String, String> getRegistrations() {
		return registrations;
	}

	/** Marks render only for staff viewers. */
	boolean isActive() {
		return ClanRanks.isDeputyOwnerPlus(client);
	}

	private void update(EventsResponse response) {
		Map<String, String> map = new HashMap<>();
		if (response != null && response.getData() != null && response.getData().getEvents() != null) {
			for (EventsResponse.EventSummary event : response.getData().getEvents()) {
				if (!event.isUpcoming() || event.getRegistrations() == null) continue;
				for (EventsResponse.EventRegistration reg : event.getRegistrations()) {
					if (!reg.isRegistered() || reg.getOsrsNickname() == null) continue;
					map.merge(Text.standardize(reg.getOsrsNickname()), event.getName(), (a, b) -> a + ", " + b);
				}
			}
		}
		registrations = Map.copyOf(map);
	}
}

package com.revalclan.events;

import com.revalclan.util.ClanSidepanel;
import net.runelite.api.Client;
import net.runelite.api.FontTypeFace;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.Map;

/**
 * Draws {@link RegistrationMarks}' checkmark after marked names in the clan
 * sidepanel and shows which upcoming event(s) they registered for on hover.
 */
public class RegistrationMarksOverlay extends Overlay {
	private static final Color GOLD = new Color(255, 200, 60);
	private static final Color CHECK_GREEN = new Color(0x3FBF4A);

	private final Client client;
	private final RegistrationMarks marks;
	private final TooltipManager tooltipManager;

	@Inject
	public RegistrationMarksOverlay(Client client, RegistrationMarks marks, TooltipManager tooltipManager) {
		this.client = client;
		this.marks = marks;
		this.tooltipManager = tooltipManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g) {
		Map<String, String> registrations = marks.getRegistrations();
		if (registrations.isEmpty() || !marks.isActive()) {
			return null;
		}
		Widget list = client.getWidget(InterfaceID.ClansSidepanel.PLAYERLIST);
		if (list == null || list.isHidden()) {
			return null;
		}
		Rectangle viewport = list.getBounds();
		if (viewport == null) {
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		// Clip to the list like the game does, so half-scrolled rows don't
		// leak checkmarks outside the box
		java.awt.Shape prevClip = g.getClip();
		g.clip(viewport);
		Point mouse = client.getMouseCanvasPosition();

		ClanSidepanel.eachNameRow(client, child -> {
			String events = registrations.get(Text.standardize(child.getText()));
			if (events == null) {
				return;
			}
			Rectangle bounds = child.getBounds();
			if (bounds == null || !viewport.intersects(bounds)) {
				return;
			}

			FontTypeFace font = child.getFont();
			String plain = Text.removeTags(child.getText());
			int textEnd = bounds.x + (font != null ? font.getTextWidth(plain) : bounds.width);
			drawCheck(g, textEnd + 4, bounds.y + bounds.height / 2);

			if (bounds.contains(mouse.getX(), mouse.getY()) && viewport.contains(mouse.getX(), mouse.getY())) {
				tooltipManager.add(new Tooltip("Registered: " + ColorUtil.wrapWithColorTag(events, GOLD)));
			}
		});
		g.setClip(prevClip);
		return null;
	}

	private void drawCheck(Graphics2D g, int x, int centerY) {
		int[] xs = {x, x + 3, x + 8};
		int[] ys = {centerY, centerY + 3, centerY - 4};
		g.setStroke(new BasicStroke(2, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(new Color(0, 0, 0, 160));
		g.translate(1, 1);
		g.drawPolyline(xs, ys, 3);
		g.translate(-1, -1);
		g.setColor(CHECK_GREEN);
		g.drawPolyline(xs, ys, 3);
	}
}

package com.revalclan.notifiers;

import com.google.gson.JsonObject;
import com.revalclan.RevalClanConfig;
import com.revalclan.util.ClanMembership;
import com.revalclan.util.EventFilterManager;
import com.revalclan.util.ScreenshotService;
import com.revalclan.util.WebhookService;
import com.revalclan.util.Worlds;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;

/**
 * Base class for all notification types (loot, death, pets, etc.)
 */
@Slf4j
public abstract class BaseNotifier {
	@Inject protected Client client;

	@Inject protected WebhookService webhookService;

	@Inject protected RevalClanConfig config;

	@Inject protected EventFilterManager filterManager;

	@Inject protected ClanMembership clanMembership;

	@Inject protected ItemManager itemManager;

	@Inject protected ScreenshotService screenshotService;

	/**
	 * Check if this notifier should be active
	 * @return true if the notifier is enabled and conditions are met
	 */
	public abstract boolean isEnabled();

	/**
	 * Get the event type identifier for this notifier
	 * @return Event type string (e.g., "LOOT", "DEATH", "PET")
	 */
	protected abstract String getEventType();

	/**
	 * Clan-membership gate applied before every send — the cached per-login
	 * answer, so a hop's channel drop or a closed clan channel never swallows
	 * an event. Notifiers whose event fires after the login screen resets the
	 * cache (LOGOUT) override this; their callers gate on the previous answer.
	 */
	protected boolean passesClanCheck() {
		return clanMembership.isMember();
	}

	protected void sendNotification(Map<String, Object> data) {
		sendNotification(getEventType(), data, null);
	}

	/**
	 * Send, optionally handing the parsed JSON response to the consumer.
	 * Consumer runs on the HTTP thread — must not touch the client.
	 */
	protected void sendNotification(Map<String, Object> data, Consumer<JsonObject> onResponse) {
		sendNotification(getEventType(), data, onResponse);
	}

	/** The one send primitive behind the two overloads above. */
	private void sendNotification(String eventType, Map<String, Object> data, Consumer<JsonObject> onResponse) {
		if (!passesClanCheck()) return;
		addEventMetadata(eventType, data, true);
		webhookService.sendDataAsync(data, onResponse);
	}

	/**
	 * Send without the inventory and equipment snapshots. For events that are a
	 * number or a name rather than a thing the player is holding (a varbit
	 * value, an item that was used up), the containers are dead weight — and a
	 * varbit can tick every 30 seconds for the length of a game.
	 */
	protected void sendCompactNotification(String eventType, Map<String, Object> data) {
		if (!passesClanCheck()) return;
		addEventMetadata(eventType, data, false);
		webhookService.sendDataAsync(data, null);
	}

	/**
	 * Captures a screenshot of the current game frame, then sends the
	 * notification with the image as its own request part (plain JSON when the
	 * capture failed).
	 * @param data The notification data
	 */
	protected void sendNotificationWithScreenshot(Map<String, Object> data) {
		if (!passesClanCheck()) return;
		addEventMetadata(getEventType(), data, true);

		screenshotService.captureScreenshot()
			.thenAccept(screenshot -> webhookService.sendDataAsync(data, screenshot, null));
	}

	/**
	 * Adds standard event metadata (type, timestamp, location, inventory, etc.) to the data map.
	 * Must be called on the game thread where client access is safe.
	 */
	private void addEventMetadata(String eventType, Map<String, Object> data, boolean includeContainers) {
		data.put("eventType", eventType);
		data.put("eventTimestamp", System.currentTimeMillis());
		data.put("accountHash", client.getAccountHash());
		data.put("username", getPlayerName());
		data.put("world", client.getWorld());
		data.put("worldFlags", Worlds.flagNames(client));

		if (client.getLocalPlayer() != null) {
			WorldPoint wp = client.getLocalPlayer().getWorldLocation();
			data.put("worldX", wp.getX());
			data.put("worldY", wp.getY());
			data.put("plane", wp.getPlane());
			data.put("regionId", wp.getRegionID());
		}

		if (includeContainers) {
			data.put("inventory", getInventoryData());
			data.put("equipment", getEquippedItems());
		}
	}

	/**
	 * Get the player's name
	 */
	protected String getPlayerName() {
		if (client.getLocalPlayer() != null) return client.getLocalPlayer().getName();
		return "Unknown";
	}

	/**
	 * Get player's equipped items using the equipment ItemContainer
	 */
	protected List<Map<String, Object>> getEquippedItems() {
		return getItemContainerData(94); // Equipment container
	}

	/**
	 * Get player's inventory data
	 */
	protected List<Map<String, Object>> getInventoryData() {
		return getItemContainerData(93); // Inventory container
	}

	/**
	 * Get items from a specific ItemContainer
	 * @param containerId The container ID (93=inventory, 94=equipment)
	 */
	private List<Map<String, Object>> getItemContainerData(int containerId) {
		List<Map<String, Object>> items = new ArrayList<>();

		ItemContainer container = client.getItemContainer(containerId);
		if (container == null) return items;

		Item[] containerItems = container.getItems();
		if (containerItems == null) return items;

		for (int i = 0; i < containerItems.length; i++) {
			Item item = containerItems[i];

			// Skip empty slots
			if (item.getId() <= 0 || item.getQuantity() <= 0) continue;

			Map<String, Object> itemData = new HashMap<>();
			itemData.put("id", item.getId());
			itemData.put("quantity", item.getQuantity());
			itemData.put("gePrice", itemManager.getItemPrice(item.getId()));
			itemData.put("slot", i);

			try {
				ItemComposition itemComp = itemManager.getItemComposition(item.getId());
				if (itemComp != null) {
					itemData.put("name", itemComp.getName());
				} else {
					itemData.put("name", "Unknown");
				}
			} catch (Exception e) {
				itemData.put("name", "Unknown");
			}

			items.add(itemData);
		}

		return items;
	}
}

package com.revalclan.notifiers;

import net.runelite.api.ChatMessageType;

import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Notifier for system chat messages - excludes player chats, private messages, clan chats, etc.
 * Useful for tracking game events, broadcasts, and system notifications for bingo/challenges.
 */
@Singleton
public class ChatNotifier extends BaseNotifier {

	/**
	 * Chat message types that are considered "system" messages.
	 * These are game-generated messages, not player-typed chats.
	 */
	private static final Set<ChatMessageType> SYSTEM_MESSAGE_TYPES = EnumSet.of(
		ChatMessageType.GAMEMESSAGE,
		ChatMessageType.SPAM,
		ChatMessageType.ENGINE,
		ChatMessageType.CONSOLE,
		ChatMessageType.MESBOX,
		ChatMessageType.DIALOG,
		ChatMessageType.OBJECT_EXAMINE,
		ChatMessageType.NPC_SAY,
		ChatMessageType.NPC_EXAMINE
	);

	private static final Pattern HTML_BR = Pattern.compile("<br>");
	private static final Pattern HTML_TAGS = Pattern.compile("<[^>]+>");

	private List<String> cachedPatternStrings = Collections.emptyList();
	private List<Pattern> cachedPatterns = Collections.emptyList();

	@Override
	public boolean isEnabled() {
		return filterManager.getFilters().isChatEnabled();
	}

	@Override
	protected String getEventType() {
		return "CHAT";
	}

	/**
	 * Handle a chat message event
	 * @param messageType The type of chat message
	 * @param source The source/sender of the message (can be null for system messages)
	 * @param message The message content
	 */
	public void onChatMessage(ChatMessageType messageType, String source, String message) {
		if (!isEnabled()) return;

		if (!SYSTEM_MESSAGE_TYPES.contains(messageType)) return;

		String cleanMessage = cleanMessage(message);

		List<String> patterns = filterManager.getFilters().getChatPatterns();

		if (!patterns.isEmpty() && !hasMatch(cleanMessage, patterns)) {
			return;
		}

		handleNotify(messageType, source, cleanMessage);
	}

	/**
	 * Clean HTML tags and formatting from a message
	 */
	private String cleanMessage(String message) {
		if (message == null) return "";
		String cleaned = HTML_BR.matcher(message).replaceAll(" ");
		return HTML_TAGS.matcher(cleaned).replaceAll("").trim();
	}

	/**
	 * Check if the message matches any configured patterns
	 * @param message The message to check
	 * @param patterns List of regex pattern strings from the API
	 */
	private boolean hasMatch(String message, List<String> patterns) {
		if (!patterns.equals(cachedPatternStrings)) {
			List<Pattern> compiled = new ArrayList<>(patterns.size());
			for (String patternStr : patterns) {
				try {
					compiled.add(Pattern.compile(patternStr, Pattern.CASE_INSENSITIVE));
				} catch (Exception e) {}
			}
			cachedPatterns = compiled;
			cachedPatternStrings = new ArrayList<>(patterns);
		}

		for (Pattern pattern : cachedPatterns) {
			if (pattern.matcher(message).find()) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Send a chat notification
	 */
	private void handleNotify(ChatMessageType messageType, String source, String message) {
		Map<String, Object> chatData = new HashMap<>();
		chatData.put("messageType", messageType.name());
		chatData.put("message", message);

		if (source != null && !source.isEmpty()) {
			chatData.put("source", source);
		}

		chatData.put("category", categorizeMessage(messageType, message));

		sendNotification(chatData);
	}

	/**
	 * Categorize the message type for easier processing
	 */
	private String categorizeMessage(ChatMessageType type, String message) {
		switch (type) {
			case GAMEMESSAGE:
			case ENGINE:
				return "GAME";
			case SPAM:
				return "SPAM";
			case CONSOLE:
				return "CONSOLE";
			case MESBOX:
			case DIALOG:
				return "DIALOG";
			case OBJECT_EXAMINE:
			case NPC_EXAMINE:
				return "EXAMINE";
			case NPC_SAY:
				return "NPC";
			default:
				return "OTHER";
		}
	}
}

