	/**
	 * Check if an item name is a known pet
	 */
	private boolean isPetItem(String itemName) {
		if (itemName == null || itemName.isEmpty()) return false;

		// Normalize the item name (lowercase, trim)
		String normalized = itemName.toLowerCase().trim();

		// Direct match
		if (PET_NAMES.contains(normalized)) {
			return true;
		}

		// Check if it starts with "pet " and the rest matches
		if (normalized.startsWith("pet ")) {
			String withoutPrefix = normalized.substring(4).trim();
			return PET_NAMES.contains(withoutPrefix) || PET_NAMES.contains(normalized);
		}

		return false;
	}

	/** Pre-compiled patterns for cleaning usernames (avoids recompiling on every call). */
	private static final Pattern LEADING_NON_WORD = Pattern.compile("^[^\\w\\s]+");
	private static final Pattern CONTROL_CHARS = Pattern.compile("[\\u0000-\\u001F\\u007F-\\u009F]");
	private static final Pattern GENERAL_PUNCTUATION = Pattern.compile("[\\u2000-\\u206F]");
	private static final Pattern CURRENCY_SYMBOLS = Pattern.compile("[\\u20A0-\\u20CF]");
	private static final Pattern ARROWS = Pattern.compile("[\\u2190-\\u21FF]");
	private static final Pattern MISC_SYMBOLS = Pattern.compile("[\\u2600-\\u26FF]");
	private static final Pattern DINGBATS = Pattern.compile("[\\u2700-\\u27BF]");

	/**
	 * Clean username by removing icons, special characters, and extra whitespace.
	 * Handles Ironman icons and other special characters that appear before usernames.
	 */
	private String cleanUsername(String username) {
		if (username == null) return "";

		String cleaned = LEADING_NON_WORD.matcher(username).replaceAll("");
		cleaned = CONTROL_CHARS.matcher(cleaned).replaceAll("");
		cleaned = GENERAL_PUNCTUATION.matcher(cleaned).replaceAll("");
		cleaned = CURRENCY_SYMBOLS.matcher(cleaned).replaceAll("");
		cleaned = ARROWS.matcher(cleaned).replaceAll("");
		cleaned = MISC_SYMBOLS.matcher(cleaned).replaceAll("");
		cleaned = DINGBATS.matcher(cleaned).replaceAll("");
		return cleaned.trim();
	}
}

package com.revalclan.notifiers;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;

@Slf4j
@Singleton
public class QuestNotifier extends BaseNotifier {
	@Override
	public boolean isEnabled() {
		return filterManager.getFilters().isQuestEnabled();
	}

	@Override
	protected String getEventType() {
		return "QUEST";
	}

	public void onWidgetLoaded(WidgetLoaded event) {
		if (!isEnabled()) return;

		if (event.getGroupId() == InterfaceID.QUESTSCROLL) {
			Widget questTitle = client.getWidget(InterfaceID.Questscroll.QUEST_TITLE);
			if (questTitle != null) {
				String questText = questTitle.getText();
				handleQuestCompletion(questText);
			}
		}
	}

	private void handleQuestCompletion(String questText) {
		// Parse quest name from the widget text
		String questName = parseQuestName(questText);
		if (questName == null) return;

		int questPoints = client.getVarpValue(VarPlayerID.QP);
		int completedQuests = client.getVarbitValue(VarbitID.QUESTS_COMPLETED_COUNT);
		int totalQuests = client.getVarbitValue(VarbitID.QUESTS_TOTAL_COUNT);

		Map<String, Object> questData = new HashMap<>();
		questData.put("questName", questName);
		questData.put("questPoints", questPoints);
		questData.put("completedQuests", completedQuests);
		questData.put("totalQuests", totalQuests);

		sendNotification(questData);
	}

	private String parseQuestName(String questText) {
		if (questText == null) return null;

		String[] lines = questText.split("\n");
		if (lines.length >= 3) {
			String name = lines[2].replace("!", "").trim();
			return name.isEmpty() ? null : name;
		}
		return null;
	}
}

package com.revalclan.notifiers;

import com.revalclan.PlayerDataCollector;
import com.revalclan.util.SyncStateManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Map;

/**
 * Full account sync — manual button press or server-requested fingerprint
 * repair. ALWAYS sends the full state.
 */
@Singleton
public class SyncNotifier extends BaseNotifier {
	@Inject
	private PlayerDataCollector dataCollector;

	@Inject
	private SyncStateManager syncStateManager;

	@Override
	public boolean isEnabled() {
		return true;
	}

	@Override
	protected String getEventType() {
		return "SYNC";
	}

	/**
	 * Trigger a full account sync.
	 * Collects all player data (collection log, quests, diaries, combat achievements, etc.)
	 * and sends it to the webhook.
	 */
	public void triggerSync() {
		Map<String, Object> data = dataCollector.collectSyncData();
		sendNotification(data, syncStateManager.ackHandler(client.getAccountHash()));
	}
}

package com.revalclan.notifiers;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * Reports the value of varbits the backend asked to watch (varbits.watch on
 * the event-filters payload).
 *
 * Some content keeps its score in a varbit and nowhere else: Volcanic Mine
 * points accrue in one during a game, with no chat line and no item. Rises are
 * coalesced and flushed every {@link #FLUSH_INTERVAL_TICKS} so a game does not
 * produce an event per swing; a fall flushes at once, and the peak is sent
 * before the new value so the backend never misses what was banked before a
 * reset.
 */
@Slf4j
@Singleton
public class VarbitNotifier extends BaseNotifier {
	/** About 30 seconds. */
	private static final int FLUSH_INTERVAL_TICKS = 50;

	/** Latest value observed per watched varbit. */
	private final Map<Integer, Integer> latest = new HashMap<>();
	/** Last value the backend was told per watched varbit. */
	private final Map<Integer, Integer> sent = new HashMap<>();
	private int ticksSinceFlush = 0;

	@Inject private ClientThread clientThread;

	/**
	 * Send the current value of every watched varbit. A varbit only raises an
	 * event when it changes, so without this the backend's first sighting would
	 * be the value AFTER a player's first deposit, and that deposit would be
	 * lost to the baseline. Called after every filter fetch (login and every
	 * ~10 minutes), unconditionally: the fetch that turns an event live is what
	 * has to establish the pre-event balance.
	 */
	public void syncBaselines() {
		clientThread.invokeLater(() -> {
			if (client.getGameState() != GameState.LOGGED_IN || !isEnabled()) return;
			for (int id : filterManager.getFilters().getVarbitWatch()) {
				int value = client.getVarbitValue(id);
				latest.put(id, value);
				sent.put(id, value);
				log.debug("[Reval] varbit baseline {} = {}", id, value);
				Map<String, Object> data = new HashMap<>();
				data.put("varbitId", id);
				data.put("value", value);
				sendCompactNotification("VARBIT_CHANGED", data);
			}
		});
	}

	@Override
	public boolean isEnabled() {
		return !filterManager.getFilters().getVarbitWatch().isEmpty();
	}

	@Override
	protected String getEventType() {
		return "VARBIT_CHANGED";
	}

	public void onVarbitChanged(VarbitChanged event) {
		int id = event.getVarbitId();
		if (id < 0) return;
		Set<Integer> watched = filterManager.getFilters().getVarbitWatch();
		if (!watched.contains(id)) return;

		int value = event.getValue();
		Integer previous = latest.put(id, value);
		log.debug("[Reval] watched varbit {} -> {} (was {})", id, value, previous);

		if (previous != null && value < previous) {
			flush(id, previous);
			flush(id, value);
		}
	}

	public void onGameTick() {
		if (latest.isEmpty() || !isEnabled()) return;
		if (++ticksSinceFlush < FLUSH_INTERVAL_TICKS) return;
		ticksSinceFlush = 0;
		for (Map.Entry<Integer, Integer> entry : latest.entrySet()) {
			flush(entry.getKey(), entry.getValue());
		}
	}

	private void flush(int id, int value) {
		Integer last = sent.get(id);
		if (last != null && last == value) return;
		sent.put(id, value);

		Map<String, Object> data = new HashMap<>();
		data.put("varbitId", id);
		data.put("value", value);
		if (last != null) data.put("previous", last);
		log.debug("[Reval] VARBIT_CHANGED {} = {} (previous {})", id, value, last);
		sendCompactNotification("VARBIT_CHANGED", data);
	}

	/** Logged out or hopped: whatever we knew belongs to a session that is over. */
	public void reset() {
		latest.clear();
		sent.clear();
		ticksSinceFlush = 0;
	}
}

package com.revalclan.pbs;

import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Locale;
import java.util.Map;

/**
 * Captures the server-side "Personal best" lines from collection log page
 * headers as the player views pages. Accumulated per account, shipped with
 * every sync.
 */
@Singleton
public class ClogPersonalBestCapture {
	private static final String CONFIG_GROUP = "revalclanclogpb";
	private static final int CLOG_GROUP = 621;
	private static final int HEADER_CHILD = 20;

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ConfigManager configManager;

	public Map<String, Object> sync() {
		return PbStore.read(configManager, CONFIG_GROUP);
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event) {
		if (event.getScriptId() == ScriptID.COLLECTION_DRAW_LIST) {
			clientThread.invokeLater(this::captureOpenPage);
		}
	}

	private void captureOpenPage() {
		Widget header = client.getWidget(CLOG_GROUP, HEADER_CHILD);
		if (header == null || configManager.getRSProfileKey() == null) return;

		Widget[] headerLines = header.getDynamicChildren();
		if (headerLines == null || headerLines.length < 2) return;

		String pageName = clean(headerLines[0]);
		if (pageName.isEmpty()) return;

		for (Widget lineWidget : headerLines) {
			String line = clean(lineWidget);
			int pbLabelAt = line.toLowerCase(Locale.ROOT).indexOf("personal best");
			if (pbLabelAt < 0) continue;

			int colonAt = line.indexOf(':', pbLabelAt);
			if (colonAt < 0) continue;

			String pbLabel = line.substring(0, colonAt);
			double pbSeconds = parseTime(line.substring(colonAt + 1).trim());
			if (pbSeconds > 0) {
				configManager.setRSProfileConfiguration(CONFIG_GROUP, key(pageName, pbLabel), String.valueOf(pbSeconds));
			}
		}
	}

	/** Page name + any label qualifier beyond "Personal best" (raid modes / team sizes). */
	private static String key(String pageName, String pbLabel) {
		String qualifier = pbLabel.toLowerCase(Locale.ROOT).replace("personal best", " ").replaceAll("[()]", " ");
		return (pageName + " " + qualifier).toLowerCase(Locale.ROOT).replaceAll("\\s+", " ").trim();
	}

	/** "h:mm:ss.ss" / "m:ss.ss" / "ss.ss" -> seconds; -1 when unparseable. */
	private static double parseTime(String time) {
		try {
			double seconds = 0;
			for (String part : time.split(":")) seconds = seconds * 60 + Double.parseDouble(part.trim());
			return seconds;
		} catch (NumberFormatException e) {
			return -1;
		}
	}

	/** Widget text without color tags and non-breaking spaces. */
	private static String clean(Widget widget) {
		String text = widget == null ? null : widget.getText();
		return text == null ? "" : Text.removeTags(text).replace('\u00A0', ' ').trim();
	}
}

package com.revalclan.pbs;

import net.runelite.client.config.ConfigManager;

import java.util.HashMap;
import java.util.Map;

/** Shared reader for RS-profile-scoped PB config stores (key -> seconds). */
final class PbStore {
	private PbStore() {}

	static Map<String, Object> read(ConfigManager configManager, String group) {
		Map<String, Object> pbs = new HashMap<>();
		String profile = configManager.getRSProfileKey();
		if (profile == null) return pbs;
		for (String key : configManager.getRSProfileConfigurationKeys(group, profile, "")) {
			try {
				pbs.put(key, Double.parseDouble(configManager.getRSProfileConfiguration(group, key)));
			} catch (Exception ignored) {}
		}
		return pbs;
	}
}

