import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Path2D;
import java.awt.geom.Point2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

/**
 * Trading-card style profile rendered in-game: the whole client dims and the
 * card draws centered on the canvas, fading in.
 * The accent color comes from the player's rank. Clicks and Escape close it
 * (input is consumed by {@link PlayerCardManager} while open).
 */
@Singleton
public class PlayerCardOverlay extends Overlay {
	private static final int CARD_W = 250;
	private static final int CARD_H = 384;
	private static final int GLOW = 12;
	private static final int ARC = 20;
	private static final long FADE_MS = 200;

	private final Client client;

	private volatile PlayerCardData data;
	private volatile Color accent;
	private volatile BufferedImage rankSprite;
	private volatile BufferedImage nextRankSprite;
	private volatile long openedAt;
	private volatile String pendingName;
	private volatile String statusText;

	@Inject
	public PlayerCardOverlay(Client client) {
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	/** Dim and show a loading message while the profile is fetched. */
	void showLoading(String playerName) {
		this.data = null;
		this.rankSprite = null;
		this.nextRankSprite = null;
		this.statusText = "Loading Reval profile...";
		this.openedAt = System.currentTimeMillis();
		this.pendingName = playerName;
	}

	/** True while the card is still waiting for this player's profile. */
	boolean isLoadingFor(String playerName) {
		return data == null && playerName.equals(pendingName);
	}

	void showError(String message) {
		this.statusText = message;
	}

	void show(PlayerCardData data, Color accent) {
		this.accent = accent;
		this.data = data;
	}

	void setRankSprite(BufferedImage sprite) {
		this.rankSprite = sprite;
	}

	void setNextRankSprite(BufferedImage sprite) {
		this.nextRankSprite = sprite;
	}

	boolean isOpen() {
		return pendingName != null;
	}

	void close() {
		data = null;
		pendingName = null;
		statusText = null;
	}

	@Override
	public Dimension render(Graphics2D g) {
		if (!isOpen()) {
			return null;
		}
		PlayerCardData card = data;

		float fade = Math.min(1f, (System.currentTimeMillis() - openedAt) / (float) FADE_MS);
		int canvasW = client.getCanvasWidth();
		int canvasH = client.getCanvasHeight();

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// Dim the whole client so the card is in focus
		g.setColor(new Color(0, 0, 0, (int) (150 * fade)));
		g.fillRect(0, 0, canvasW, canvasH);

		Composite prevComposite = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, fade));

		Font small = FontManager.getRunescapeSmallFont();
		int cx = canvasW / 2;

		if (card == null || accent == null) {
			// Loading or error text instead of the card
			centerText(g, statusText != null ? statusText : "Loading Reval profile...",
				FontManager.getRunescapeFont(), UIConstants.ACCENT_GOLD, cx, canvasH / 2);
			centerText(g, "Click or press Esc to close", small, new Color(255, 255, 255, 110),
				cx, canvasH / 2 + 22);
			g.setComposite(prevComposite);
			return null;
		}

		int x = (canvasW - CARD_W) / 2;
		int y = (canvasH - CARD_H) / 2;
		drawFrame(g, accent, x, y);
		String hoveredWin = drawContent(g, card, accent, x, y);

		centerText(g, "Click or press Esc to close", small, new Color(255, 255, 255, 110),
			x + CARD_W / 2, y + CARD_H + GLOW + 16);

		if (hoveredWin != null) {
			drawWinTooltip(g, hoveredWin);
		}

		g.setComposite(prevComposite);
		return null;
	}

	/** Classic frame with the foil radial color: glow, gradient, sheen. */
	private void drawFrame(Graphics2D g, Color accent, int x, int y) {
		g.setStroke(new BasicStroke(1));
		for (int i = GLOW; i > 0; i--) {
			g.setColor(Colors.withAlpha(accent, Math.max(1, 24 - i * 2)));
			g.drawRoundRect(x - i, y - i, CARD_W + i * 2, CARD_H + i * 2, ARC + i, ARC + i);
		}

		g.setPaint(new GradientPaint(x, y, new Color(0x24242f), x, y + CARD_H, new Color(0x121219)));
		g.fillRoundRect(x, y, CARD_W, CARD_H, ARC, ARC);

		Shape prevClip = g.getClip();
		g.clip(new RoundRectangle2D.Float(x, y, CARD_W, CARD_H, ARC, ARC));
		g.setPaint(new RadialGradientPaint(new Point2D.Float(x + CARD_W / 2f, y + 60), CARD_W,
			new float[]{0f, 1f}, new Color[]{Colors.withAlpha(accent, 78), new Color(0, 0, 0, 0)}));
		g.fillRect(x, y, CARD_W, CARD_H);

		g.setPaint(new GradientPaint(x, y + CARD_H, new Color(255, 255, 255, 0),
			x + CARD_W, y, new Color(255, 255, 255, 16)));
		int band = 90;
		g.fillPolygon(
			new int[]{x + CARD_W - band - 50, x + CARD_W - 50, x + CARD_W, x + CARD_W - band},
			new int[]{y + CARD_H, y, y, y + CARD_H}, 4);
		g.setClip(prevClip);

		g.setColor(Colors.withAlpha(accent, 210));
		g.setStroke(new BasicStroke(2f));
		g.drawRoundRect(x, y, CARD_W - 1, CARD_H - 1, ARC, ARC);
	}

	/** Returns the event name of a hovered win star, or null. */
	private String drawContent(Graphics2D g, PlayerCardData card, Color accent, int x, int y) {
		Font small = FontManager.getRunescapeSmallFont();
		Font bold = FontManager.getRunescapeBoldFont();
		Font nameFont = bold.deriveFont(Font.BOLD, 20f);
		Font pointsFont = bold.deriveFont(Font.BOLD, 24f);

		int cx = x + CARD_W / 2;
		int cy = y + 26;

		BufferedImage sprite = rankSprite;
		if (sprite != null) {
			int sw = Math.min(24, sprite.getWidth());
			int sh = Math.min(24, sprite.getHeight());
			g.drawImage(sprite, cx - sw / 2, cy - sh / 2, sw, sh, null);
		}
		cy += 24;
		centerText(g, card.getRankName().toUpperCase(), small, accent, cx, cy);
		cy += 26;
		centerText(g, card.getPlayerName(), nameFont, UIConstants.TEXT_PRIMARY, cx, cy);
		cy += 12;
		String hoveredWin = drawWinStars(g, card, cx, cy);
		cy += 32;
		centerText(g, NumberFmt.group(card.getPoints()), pointsFont, UIConstants.ACCENT_GOLD, cx, cy);
		cy += 16;
		centerText(g, "REVAL POINTS", small, UIConstants.TEXT_MUTED, cx, cy);
		cy += 20;

		if (card.getRankProgress() >= 0) {
			int barW = CARD_W - 70;
			g.setColor(new Color(255, 255, 255, 26));
			g.fillRoundRect(cx - barW / 2, cy, barW, 5, 5, 5);
			int fill = (int) Math.round(barW * Math.min(1.0, Math.max(0.0, card.getRankProgress())));
			if (fill > 0) {
				g.setColor(accent);
				g.fillRoundRect(cx - barW / 2, cy, fill, 5, 5, 5);
			}
			cy += 22;
			drawProgressRow(g, card, small, cx, cy);
		} else {
			cy += 22;
		}
		cy += 16;

		int gap = 8;
		int tileW = (CARD_W - 40 - gap) / 2;
		int tileH = 48;
		String[][] stats = {
			{NumberFmt.group(card.getDropPoints()) + "M", "GP from drops"},
			{String.valueOf(card.getPetCount()), "Pets"},
			{String.valueOf(card.getClogCount()), "Collection log"},
			{card.getDiaryTasksDone() + "/" + card.getDiaryTasksTotal(), "Reval diary tasks"},
		};
		for (int i = 0; i < stats.length; i++) {
			int tx = x + 20 + (i % 2) * (tileW + gap);
			int ty = cy + (i / 2) * (tileH + gap);
			g.setColor(Colors.withAlpha(accent, 18));
			g.fillRoundRect(tx, ty, tileW, tileH, 10, 10);
			g.setStroke(new BasicStroke(1f));
			g.setColor(Colors.withAlpha(accent, 60));
			g.drawRoundRect(tx, ty, tileW, tileH, 10, 10);
			centerText(g, stats[i][0], bold, UIConstants.TEXT_PRIMARY, tx + tileW / 2, ty + 26);
			centerText(g, stats[i][1], small, UIConstants.TEXT_MUTED, tx + tileW / 2, ty + 42);
		}

		int fy = y + CARD_H - 14;
		g.setFont(bold);
		drawShadowed(g, "REVAL", x + 20, fy, UIConstants.ACCENT_GOLD);
		if (card.getMemberSince() != null) {
			g.setFont(small);
			String since = "Member since " + card.getMemberSince();
			int sinceW = g.getFontMetrics().stringWidth(since);
			drawShadowed(g, since, x + CARD_W - 20 - sinceW, fy, UIConstants.TEXT_MUTED);
		}
		return hoveredWin;
	}

	/** One star per event win, centered; returns the hovered star's event. */
	private String drawWinStars(Graphics2D g, PlayerCardData card, int cx, int centerY) {
		java.util.List<String> wins = card.getEventWins();
		if (wins == null || wins.isEmpty()) {
			return null;
		}
		int spacing = 18;
		int startX = cx - (wins.size() - 1) * spacing / 2;
		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		String hovered = null;

		for (int i = 0; i < wins.size(); i++) {
			int sx = startX + i * spacing;
			boolean hot = Math.abs(mouse.getX() - sx) <= 9 && Math.abs(mouse.getY() - centerY) <= 9;
			if (hot) {
				hovered = wins.get(i);
			}
			Shape star = star(sx, centerY, hot ? 8 : 7, hot ? 3.6 : 3.2);
			Graphics2D shadow = (Graphics2D) g.create();
			shadow.translate(1, 1);
			shadow.setColor(new Color(0, 0, 0, 160));
			shadow.fill(star);
			shadow.dispose();
			g.setColor(hot ? new Color(0xFFD75E) : UIConstants.ACCENT_GOLD);
			g.fill(star);
			g.setColor(new Color(0x8A6D25));
			g.setStroke(new BasicStroke(1f));
			g.draw(star);
		}
		return hovered;
	}

	private Shape star(int cx, int cy, double outer, double inner) {
		Path2D.Double path = new Path2D.Double();
		for (int i = 0; i < 10; i++) {
			double r = i % 2 == 0 ? outer : inner;
			double angle = Math.PI / 5 * i - Math.PI / 2;
			double px = cx + Math.cos(angle) * r;
			double py = cy + Math.sin(angle) * r;
			if (i == 0) {
				path.moveTo(px, py);
			} else {
				path.lineTo(px, py);
			}
		}
		path.closePath();
		return path;
	}

	/** Small tooltip near the cursor naming the won event. */
	private void drawWinTooltip(Graphics2D g, String eventName) {
		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		String text = "Won: " + eventName;
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();
		int w = fm.stringWidth(text) + 16;
		int h = fm.getHeight() + 8;
		int tx = Math.min(mouse.getX() + 12, client.getCanvasWidth() - w - 4);
		int ty = mouse.getY() - h - 6;

		g.setColor(new Color(0, 0, 0, 210));
		g.fillRoundRect(tx, ty, w, h, 6, 6);
		g.setColor(Colors.withAlpha(UIConstants.ACCENT_GOLD, 160));
		g.setStroke(new BasicStroke(1f));
		g.drawRoundRect(tx, ty, w, h, 6, 6);
		drawShadowed(g, text, tx + 8, ty + fm.getAscent() + 4, UIConstants.ACCENT_GOLD);
	}

	/** "N pts to <rank icon>" centered; falls back to the rank name until the sprite loads. */
	private void drawProgressRow(Graphics2D g, PlayerCardData card, Font small, int cx, int baselineY) {
		if (card.getNextRankName() == null) {
			centerText(g, "Max rank", small, UIConstants.TEXT_SECONDARY, cx, baselineY);
			return;
		}
		String text = NumberFmt.group(card.getPointsToNext()) + " pts to ";
		BufferedImage sprite = nextRankSprite;
		if (sprite == null) {
			centerText(g, text + card.getNextRankName(), small, UIConstants.TEXT_SECONDARY, cx, baselineY);
			return;
		}
		g.setFont(small);
		FontMetrics fm = g.getFontMetrics();
		// Aspect-fit the icon to 14px and center it on the text's midline
		double scale = Math.min(1.0, 14.0 / Math.max(sprite.getWidth(), sprite.getHeight()));
		int iconW = Math.max(1, (int) Math.round(sprite.getWidth() * scale));
		int iconH = Math.max(1, (int) Math.round(sprite.getHeight() * scale));
		int textW = fm.stringWidth(text);
		int tx = cx - (textW + 3 + iconW) / 2;
		drawShadowed(g, text, tx, baselineY, UIConstants.TEXT_SECONDARY);
		g.drawImage(sprite, tx + textW + 3, baselineY - 5 - iconH / 2, iconW, iconH, null);
	}


	private void centerText(Graphics2D g, String text, Font font, Color color, int cx, int baselineY) {
		g.setFont(font);
		FontMetrics fm = g.getFontMetrics();
		drawShadowed(g, text, cx - fm.stringWidth(text) / 2, baselineY, color);
	}

	private void drawShadowed(Graphics2D g, String text, int x, int y, Color color) {
		g.setColor(new Color(0, 0, 0, 180));
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}
}

package com.revalclan.quests;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * Manages quest completion data
 */
@Slf4j
@Singleton
public class QuestManager {
	@Inject private Client client;

	/**
	 * RuneLite's Quest enum has no quest/miniquest flag, so membership is curated
	 * here. Mirror of https://oldschool.runescape.wiki/w/Miniquests (19 as of
	 * July 2025) — update on new releases. RFD subquests are NOT miniquests;
	 * they stay in questStates.
	 */
	private static final Set<String> MINIQUEST_NAMES = Set.of(
		"Alfred Grimhand's Barcrawl",
		"Barbarian Training",
		"Bear Your Soul",
		"Curse of the Empty Lord",
		"Daddy's Home",
		"The Enchanted Key",
		"Enter the Abyss",
		"Family Pest",
		"The Frozen Door",
		"The General's Shadow",
		"His Faithful Servants",
		"Hopespear's Will",
		"In Search of Knowledge",
		"Into the Tombs",
		"Lair of Tarn Razorlor",
		"Mage Arena I",
		"Mage Arena II",
		"Skippy and the Mogres",
		"Vale Totems"
	);

	/**
	 * Sync and get quest completion data, miniquests separated from quests
	 */
	public Map<String, Object> sync() {
		Map<String, Object> questData = new HashMap<>();
		Map<String, String> questStates = new HashMap<>();
		Map<String, String> miniquestStates = new HashMap<>();

		for (Quest quest : Quest.values()) {
			QuestState state = quest.getState(client);
			if (MINIQUEST_NAMES.contains(quest.getName())) {
				miniquestStates.put(quest.getName(), state.name());
			} else {
				questStates.put(quest.getName(), state.name());
			}
		}

		questData.put("questPoints", client.getVarpValue(101));
		questData.put("questStates", questStates);
		questData.put("miniquestStates", miniquestStates);

		return questData;
	}
}

package com.revalclan.session;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.List;

/**
 * Crash-safe persistence for in-progress sessions: one JSON file per session
 * under {@code ~/.runelite/reval-clan/sessions/}, written synchronously.
 *
 * Why not the RuneLite config store: it buffers in memory and only reaches
 * disk on a 5-minute timer or a graceful exit. Verified 2026-09-10 — three
 * consecutive hard kills lost three sessions and resurrected a deleted one.
 * A file written on every persist survives everything short of power loss.
 */
@Slf4j
@Singleton
public class SessionStore {
	private static final String DIR_NAME = "reval-clan/sessions";
	/** Undelivered files older than this are dropped at recovery */
	private static final long MAX_AGE_MS = 14L * 24 * 60 * 60 * 1000;

	@Inject private Gson gson;

	/** Persisted shape. {@code summary} stays a JsonObject so numbers survive exactly. */
	public static class PersistedSession {
		public long accountHash;
		public String username;
		public int world;
		public List<String> worldFlags;
		/** Membership was proven while this session was recorded — safe to send at startup */
		public boolean member;
		public JsonObject summary;

		public String sessionId() {
			try {
				return summary.get("sessionId").getAsString();
			} catch (Exception e) {
				return null;
			}
		}

		public long startedAt() {
			try {
				return summary.get("startedAt").getAsLong();
			} catch (Exception e) {
				return 0;
			}
		}
	}

	private File dir() {
		File d = new File(RuneLite.RUNELITE_DIR, DIR_NAME);
		if (!d.exists() && !d.mkdirs()) {
			log.warn("Could not create session store directory {}", d);
		}
		return d;
	}

	private File fileFor(String sessionId) {
		return new File(dir(), sessionId + ".json");
	}

	/** Atomic write: temp file then move, so a crash mid-write never leaves a torn file. */
	public void write(PersistedSession session) {
		String id = session.sessionId();
		if (id == null) return;
		Path target = fileFor(id).toPath();
		Path tmp = target.resolveSibling(id + ".tmp");
		try {
			Files.write(tmp, gson.toJson(session).getBytes(StandardCharsets.UTF_8));
			try {
				Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			} catch (IOException atomicUnsupported) {
				Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING);
			}
		} catch (IOException e) {
			log.warn("Failed to persist session {}: {}", id, e.getMessage());
		}
	}

	public void delete(String sessionId) {
		if (sessionId == null) return;
		try {
			Files.deleteIfExists(fileFor(sessionId).toPath());
		} catch (IOException e) {
			log.warn("Failed to delete persisted session {}: {}", sessionId, e.getMessage());
		}
	}

	/** Every readable persisted session, newest first. Unreadable or expired files are removed. */
	public List<PersistedSession> readAll() {
		List<PersistedSession> out = new ArrayList<>();
		File[] files = dir().listFiles((d, name) -> name.endsWith(".json"));
		if (files == null) return out;
		long now = System.currentTimeMillis();
		for (File f : files) {
			PersistedSession session = null;
			try {
				session = gson.fromJson(new String(Files.readAllBytes(f.toPath()), StandardCharsets.UTF_8), PersistedSession.class);
			} catch (Exception ignored) {}
			if (session == null || session.summary == null || session.sessionId() == null
				|| now - session.startedAt() > MAX_AGE_MS) {
				if (!f.delete()) log.warn("Could not remove stale session file {}", f);
				continue;
			}
			out.add(session);
		}
		out.sort((a, b) -> Long.compare(b.startedAt(), a.startedAt()));
		return out;
	}
}

package com.revalclan.session;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.revalclan.session.SessionStore.PersistedSession;
import com.revalclan.util.ClanMembership;
import com.revalclan.util.WebhookService;
import com.revalclan.util.Worlds;
import lombok.extern.slf4j.Slf4j;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.function.Consumer;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

/**
 * Accumulates the play session client-side and delivers it three ways:
 * <ul>
 *   <li><b>SESSION_HEARTBEAT</b> every ~10 minutes while playing, so the session
 *       exists on the server before it ends (live admin view; a crash costs at
 *       most one interval).</li>
 *   <li>The final summary attached to <b>LOGOUT</b>, or sent as a standalone
 *       <b>SESSION_SUMMARY</b> when a world hop cuts the session.</li>
 *   <li>A <b>SESSION_SUMMARY</b> replay of any session whose final summary the
 *       server never acknowledged — at startup and at every login.</li>
 * </ul>
 * Every persist goes straight to disk ({@link SessionStore}); the local copy is
 * deleted only when the server answers {@code sessionStored} = stored, duplicate
 * or rejected. The server dedupes on sessionId, so a replay can never double-store.
 *
 * A session starts the moment the player is logged in — before clan membership
 * is known — and accumulates regardless; only SENDING is gated on membership.
 * All state lives on the client thread: webhook callbacks bounce back through
 * {@link ClientThread} before touching it.
 */
@Slf4j
@Singleton
public class SessionTracker {
	/** Persist at most once per this many ticks (~30s), and only when dirty */
	private static final int PERSIST_INTERVAL_TICKS = 50;
	/** Running summary to the server every ~10 minutes */
	private static final int HEARTBEAT_INTERVAL_TICKS = 1000;
	/** Malfunction guard (deaths) */
	private static final int MAX_LIST_ENTRIES = 1000;

	/** Character Summary tab counters (Jagex varps) → summary key */
	private static final Map<String, Integer> COUNTER_VARPS = new LinkedHashMap<>();
	static {
		COUNTER_VARPS.put("monstersKilled", VarPlayerID.TRACKING_MONSTERS_KILLED);
		COUNTER_VARPS.put("bossesKilled", VarPlayerID.TRACKING_BOSSES_KILLED);
		COUNTER_VARPS.put("deaths", VarPlayerID.TRACKING_DEATHS);
		COUNTER_VARPS.put("cluesCompleted", VarPlayerID.TRACKING_CLUES_COMPLETED);
		COUNTER_VARPS.put("coinsGained", VarPlayerID.TRACKING_COINS_GAINED);
		COUNTER_VARPS.put("coinsLost", VarPlayerID.TRACKING_COINS_LOST);
	}

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private Gson gson;
	@Inject private WebhookService webhookService;
	@Inject private SessionStore store;
	@Inject private ClanMembership membership;

	@Setter private Consumer<JsonObject> onHeartbeatResponse;
	private boolean active = false;
	private boolean dirty = false;
	private int ticksSincePersist = 0;
	private int ticksSinceHeartbeat = 0;

	private String sessionId;
	private long startedAtMs;
	private long lastUpdateMs;
	private String username;
	private long accountHash;
	private int world;
	private List<String> worldFlags;
	private Map<String, Object> startSnapshot;
	private Map<String, Object> endSnapshot;
	private final Map<String, Integer> kills = new HashMap<>();
	private final Map<String, Integer> clues = new HashMap<>();
	private long totalLootValue = 0;
	private final List<Map<String, Object>> deaths = new ArrayList<>();
	private int playtimeMinutes = 0;
	private Map<String, Integer> countersStart;
	private Map<String, Integer> countersEnd;

	/** Summaries sent and not yet answered — a login right after startup must not send them twice */
	private final Set<String> inFlight = new HashSet<>();

	// ------------------------------------------------------------------ lifecycle

	/**
	 * Start a session if none is running (client thread, logged in). Idempotent:
	 * LOGGED_IN fires after every region load and reconnect, and only the first
	 * one after a login or a hop should open a segment. Any world, any clan
	 * state — the backend gates on the worldFlags captured here and membership
	 * gates sending.
	 */
	public void startSession() {
		if (active) return;
		resetState();
		sessionId = UUID.randomUUID().toString();
		startedAtMs = System.currentTimeMillis();
		lastUpdateMs = startedAtMs;
		username = playerName();
		accountHash = client.getAccountHash();
		world = client.getWorld();
		worldFlags = Worlds.flagNames(client);
		startSnapshot = buildSnapshot();
		endSnapshot = startSnapshot;
		readPlaytime();
		active = true;
		dirty = true;
		log.info("Session started: {} world={} flags={}", sessionId, world, worldFlags);
	}

	/**
	 * Finalize (clean logout) and return the summary for the LOGOUT payload, or
	 * null. The persisted copy is kept until the server acks it.
	 */
	public Map<String, Object> finalizeSession() {
		if (!active) return null;
		Map<String, Object> summary = buildSummary("logout", touch());
		persist(summary);
		reset();
		return summary;
	}

	/**
	 * A world hop ends this session (each row is one world). The summary goes
	 * out now as a standalone SESSION_SUMMARY when membership is proven;
	 * otherwise the file waits for a login on this account that proves it.
	 */
	public void cutForHop() {
		if (!active) return;
		PersistedSession persisted = persist(buildSummary("hop", touch()));
		reset();
		if (persisted.member) send(persisted);
	}

	/** In-memory only — a persisted session replays as 'recovered' later. */
	public void reset() {
		active = false;
		resetState();
	}

	// ------------------------------------------------------------------ ticking

	/** Client thread, every tick while logged in — regardless of clan state. */
	public void onGameTick() {
		if (!active) return;

		// Player, skills and varps can land a tick or two after LOGGED_IN — fill the blanks
		if (username == null) username = playerName();
		if (snapshotEmpty(startSnapshot)) {
			startSnapshot = buildSnapshot();
			endSnapshot = startSnapshot;
			if (!snapshotEmpty(startSnapshot)) dirty = true;
		}
		readCounters();

		// Pure skilling fires no accumulator event — treat XP movement as dirtiness
		if (xpChangedSinceSnapshot()) {
			touch();
			dirty = true;
		}

		ticksSincePersist++;
		if (dirty && ticksSincePersist >= PERSIST_INTERVAL_TICKS) {
			ticksSincePersist = 0;
			dirty = false;
			persist(buildSummary("recovered", touch()));
		}

		// Keep checking changes even when this world is ineligible for session storage.
		if (++ticksSinceHeartbeat >= HEARTBEAT_INTERVAL_TICKS) {
			ticksSinceHeartbeat = 0;
			if (membership.isMember()) sendHeartbeat();
		}
	}

	/** VarClientIntChanged for ACCOUNT_SUMMARY_PLAYTIME — the server re-sends it at login, hop and region load. */
	public void onPlaytimeVarcChanged() {
		if (active && playtimeMinutes <= 0) readPlaytime();
	}

	// ------------------------------------------------------------------ accumulators

	public void addKill(String npcName) {
		if (!active || npcName == null || npcName.isEmpty()) return;
		kills.merge(npcName, 1, Integer::sum);
		dirty = true;
	}

	/** Only the total is reported; the per-item breakdown has no consumer. */
	public void addLoot(String source, int itemId, String itemName, int quantity, long gePriceEach) {
		if (!active) return;
		totalLootValue += gePriceEach * quantity;
		dirty = true;
	}

	public void addClue(String tier) {
		if (!active || tier == null || tier.isEmpty()) return;
		clues.merge(tier.toLowerCase(), 1, Integer::sum);
		dirty = true;
	}

	public void addDeath(String killedBy, long gpLost) {
		if (!active || deaths.size() >= MAX_LIST_ENTRIES) return;
		Map<String, Object> death = new HashMap<>();
		death.put("killedBy", killedBy);
		death.put("gpLost", gpLost);
		if (client.getLocalPlayer() != null) {
			net.runelite.api.coords.WorldPoint wp = client.getLocalPlayer().getWorldLocation();
			death.put("location", wp.getX() + "," + wp.getY() + "," + wp.getPlane());
		}
		death.put("timestamp", System.currentTimeMillis());
		deaths.add(death);
		dirty = true;
	}

	// ------------------------------------------------------------------ delivery + recovery

	/**
	 * Server answered a summary (any thread — hops onto the client thread).
	 * Drop the local copy only on a definitive outcome; anything else (older
	 * backend, transient error) keeps it for the next replay. The server
	 * dedupes, so keeping is always safe.
	 */
	public void confirmDelivered(String deliveredSessionId, JsonObject response) {
		if (deliveredSessionId == null) return;
		String outcome = storedOutcome(response);
		clientThread.invokeLater(() -> {
			inFlight.remove(deliveredSessionId);
			if ("stored".equals(outcome) || "duplicate".equals(outcome) || "rejected".equals(outcome)) {
				store.delete(deliveredSessionId);
				log.info("Session {} {} by server — local copy dropped", deliveredSessionId, outcome);
			} else {
				log.info("Session {} not acknowledged (sessionStored={}) — keeping local copy", deliveredSessionId, outcome);
			}
		});
	}

	/**
	 * Replay every persisted session the server has not acknowledged: those
	 * recorded while a member, plus — once THIS account has proven membership —
	 * its own files recorded before that was known. Files of other accounts on
	 * the machine stay put: nothing is ever sent for an account that never
	 * proved membership.
	 *
	 * @param provenAccountHash the account that just proved membership, or 0 at startup
	 */
	public void recoverPersistedSessions(long provenAccountHash) {
		for (PersistedSession persisted : store.readAll()) {
			String id = persisted.sessionId();
			if (id.equals(sessionId) || inFlight.contains(id)) continue;
			if (persisted.member || persisted.accountHash == provenAccountHash) send(persisted);
		}
	}

	/** The one delivery path for standalone summaries: hop cuts and replays alike. */
	private void send(PersistedSession persisted) {
		String id = persisted.sessionId();
		inFlight.add(id);
		Map<String, Object> payload = envelope("SESSION_SUMMARY", persisted.username, persisted.accountHash, persisted.world, persisted.worldFlags);
		payload.put("sessionSummary", persisted.summary);
		webhookService.sendDataAsync(payload, response -> confirmDelivered(id, response));
		log.info("Sending session {} ({})", id, persisted.summary.get("endReason"));
	}

	private void sendHeartbeat() {
		Map<String, Object> payload = envelope("SESSION_HEARTBEAT", username, accountHash, world, worldFlags);
		payload.put("sessionSummary", buildSummary(null, touch()));
		String id = sessionId;
		Consumer<JsonObject> changeHandler = onHeartbeatResponse;
		log.info("Session {} heartbeat after {} min", id, (lastUpdateMs - startedAtMs) / 60000);
		webhookService.sendDataAsync(payload, response -> {
			clientThread.invokeLater(() -> {
				if (!active || !id.equals(sessionId)) return;
				if (changeHandler != null) changeHandler.accept(response);
			});
		});
	}

	private static String storedOutcome(JsonObject response) {
		try {
			if (response != null && response.has("sessionStored") && !response.get("sessionStored").isJsonNull()) {
				return response.get("sessionStored").getAsString();
			}
		} catch (Exception ignored) {}
		return null;
	}

	private Map<String, Object> envelope(String eventType, String name, long hash, int w, List<String> flags) {
		Map<String, Object> payload = new HashMap<>();
		payload.put("eventType", eventType);
		payload.put("eventTimestamp", System.currentTimeMillis());
		payload.put("accountHash", hash);
		payload.put("username", name != null ? name : "Unknown");
		payload.put("world", w);
		if (flags != null) payload.put("worldFlags", flags);
		return payload;
	}

	// ------------------------------------------------------------------ internals

	private String playerName() {
		return client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
	}

	private void resetState() {
		sessionId = null;
		startedAtMs = 0;
		lastUpdateMs = 0;
		username = null;
		accountHash = 0;
		world = 0;
		worldFlags = null;
		startSnapshot = null;
		endSnapshot = null;
		kills.clear();
		clues.clear();
		totalLootValue = 0;
		deaths.clear();
		playtimeMinutes = 0;
		countersStart = null;
		countersEnd = null;
		dirty = false;
		ticksSincePersist = 0;
	}

	/** Refresh the end snapshot and the last-update time; returns the latter. */
	private long touch() {
		if (client.getGameState() == GameState.LOGGED_IN) {
			Map<String, Object> snapshot = buildSnapshot();
			if (!snapshotEmpty(snapshot)) endSnapshot = snapshot;
		}
		lastUpdateMs = System.currentTimeMillis();
		return lastUpdateMs;
	}

	private boolean xpChangedSinceSnapshot() {
		if (client.getGameState() != GameState.LOGGED_IN || endSnapshot == null) return false;
		Object totalXp = endSnapshot.get("totalXp");
		return totalXp instanceof Number && ((Number) totalXp).longValue() != client.getOverallExperience();
	}

	private void readPlaytime() {
		int value = client.getVarcIntValue(VarClientID.ACCOUNT_SUMMARY_PLAYTIME);
		if (value > 0 && value != playtimeMinutes) {
			playtimeMinutes = value;
			dirty = true;
		}
	}

	/**
	 * The summary-tab varps arrive as a burst of zeros followed by the real
	 * values in the same tick after login/hop, so an all-zero read is ignored:
	 * the first non-zero read fixes the start, every later one moves the end.
	 */
	private void readCounters() {
		Map<String, Integer> current = new LinkedHashMap<>();
		boolean anyNonZero = false;
		for (Map.Entry<String, Integer> e : COUNTER_VARPS.entrySet()) {
			int v = client.getVarpValue(e.getValue());
			if (v != 0) anyNonZero = true;
			current.put(e.getKey(), v);
		}
		if (!anyNonZero) return;
		if (countersStart == null) {
			countersStart = current;
			dirty = true;
		}
		if (!current.equals(countersEnd)) {
			countersEnd = current;
			dirty = true;
		}
	}

	private static boolean snapshotEmpty(Map<String, Object> snapshot) {
		if (snapshot == null) return true;
		Object totalXp = snapshot.get("totalXp");
		return !(totalXp instanceof Number) || ((Number) totalXp).longValue() <= 0;
	}

	/**
	 * Snapshot shape matches the backend's PlayerSnapshot:
	 * { skills: {name: {level, xp}}, totalLevel, totalXp, combatLevel, world }
	 */
	private Map<String, Object> buildSnapshot() {
		try {
			Map<String, Object> snapshot = new HashMap<>();
			Map<String, Map<String, Object>> skills = new HashMap<>();
			for (Skill skill : Skill.values()) {
				Map<String, Object> skillData = new HashMap<>();
				skillData.put("level", client.getRealSkillLevel(skill));
				skillData.put("xp", client.getSkillExperience(skill));
				skills.put(skill.getName().toLowerCase(), skillData);
			}
			snapshot.put("skills", skills);
			snapshot.put("totalLevel", client.getTotalLevel());
			snapshot.put("totalXp", client.getOverallExperience());
			if (client.getLocalPlayer() != null) {
				snapshot.put("combatLevel", client.getLocalPlayer().getCombatLevel());
			}
			snapshot.put("world", client.getWorld());
			return snapshot;
		} catch (Exception e) {
			return null;
		}
	}

	/** @param endReason logout | hop | recovered, or null for a heartbeat (still running) */
	private Map<String, Object> buildSummary(String endReason, long endedAtMs) {
		Map<String, Object> summary = new HashMap<>();
		summary.put("sessionId", sessionId);
		summary.put("startedAt", startedAtMs);
		summary.put("endedAt", endedAtMs);
		if (endReason != null) summary.put("endReason", endReason);
		summary.put("startSnapshot", startSnapshot);
		summary.put("endSnapshot", endSnapshot);
		summary.put("kills", new HashMap<>(kills));
		summary.put("clues", new HashMap<>(clues));
		summary.put("totalLootValue", totalLootValue);
		summary.put("deaths", new ArrayList<>(deaths));
		if (worldFlags != null) summary.put("worldFlags", worldFlags);
		if (playtimeMinutes > 0) summary.put("playtimeMinutes", playtimeMinutes);
		if (countersStart != null) summary.put("countersStart", countersStart);
		if (countersEnd != null) summary.put("countersEnd", countersEnd);
		return summary;
	}

	/** Write the summary to disk and return the persisted copy — the same object {@link #send} delivers. */
	private PersistedSession persist(Map<String, Object> summary) {
		PersistedSession persisted = new PersistedSession();
		persisted.accountHash = accountHash;
		persisted.username = username;
		persisted.world = world;
		persisted.worldFlags = worldFlags;
		persisted.member = membership.isMember();
		persisted.summary = gson.toJsonTree(summary).getAsJsonObject();
		store.write(persisted);
		if (summary.get("endReason") != null && !"recovered".equals(summary.get("endReason"))) {
			log.info("Session {} ended ({}) after {} min, member={}", sessionId, summary.get("endReason"),
				(lastUpdateMs - startedAtMs) / 60000, persisted.member);
		}
		return persisted;
	}
}

package com.revalclan.teams;

import com.revalclan.api.RevalApiService;
import com.revalclan.util.TeamColor;
import com.revalclan.api.events.ActiveTeamsResponse;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;
import java.util.HashMap;
import java.util.Map;

/**
 * Event rosters from the backend: maps clan member nicknames to their team's
 * hex color. Network fetches are cached by {@link RevalApiService}; this class
 * only derives the lookup map.
 *
 * The endpoint serves teams for events that are running or being planned, so
 * rosters are colorable from the draft onward rather than only once the event
 * starts. Empty (no coloring) when no event has teams yet or the fetch fails.
 */
@Slf4j
@Singleton
public class ActiveTeamColors {
	private final RevalApiService apiService;

	/** Standardized nickname -> team color */
	private volatile Map<String, Color> colors = Map.of();

	@Inject
	public ActiveTeamColors(RevalApiService apiService) {
		this.apiService = apiService;
	}

	public Color teamColorFor(String playerName) {
		return playerName != null ? colors.get(Text.standardize(playerName)) : null;
	}

	/** Rebuild the derived roster; the service cache throttles the network. */
	public void refresh() {
		apiService.fetchActiveTeams(
			response -> {
				Map<String, Color> map = new HashMap<>();
				if (response.getData() != null && response.getData().getTeams() != null) {
					for (ActiveTeamsResponse.Team team : response.getData().getTeams()) {
						if (team.getMembers() == null) {
							continue;
						}
						Color color = TeamColor.parse(team.getColor());
						for (String member : team.getMembers()) {
							// Newest event first in the response; first match wins
							map.putIfAbsent(Text.standardize(member), color);
						}
					}
				}
				colors = map;
			},
			error -> log.debug("Failed to fetch active event teams", error)
		);
	}

}

package com.revalclan.teams;

import com.revalclan.RevalClanConfig;
import com.revalclan.util.ClanSidepanel;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.util.ColorUtil;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;
import java.util.Set;

/**
 * Colors clan members' names by their event team, in the clan sidepanel member
 * list and in clan chat. The two surfaces are toggled independently: the list
 * is a roster you read deliberately, chat is a stream you skim, so the list is
 * colored by default and chat is not.
 *
 * Purely cosmetic; does nothing when no event has teams or both toggles are
 * off.
 */
@Singleton
public class ClanTeamColors {
	/** The list renders names white by default; used to restore on disable. */
	private static final int DEFAULT_NAME_COLOR = 0xFFFFFF;

	/** Config keys that change what this class paints. */
	private static final Set<String> WATCHED_KEYS = Set.of("teamNameColors", "teamColorsInChat");

	private final Client client;
	private final ClientThread clientThread;
	private final ActiveTeamColors activeTeams;
	private final RevalClanConfig config;

	@Inject
	public ClanTeamColors(Client client, ClientThread clientThread, ActiveTeamColors activeTeams, RevalClanConfig config) {
		this.client = client;
		this.clientThread = clientThread;
		this.activeTeams = activeTeams;
		this.config = config;
	}

	/** Recolor an already-open sidepanel; rebuilds are caught by the script hook. */
	public void startUp() {
		if (!anyColoringEnabled()) {
			return;
		}
		activeTeams.refresh();
		if (config.teamColorsInClanList()) {
			clientThread.invoke(this::recolorSidepanel);
		}
	}

	/** Restore default name colors; chat lines already colored stay as sent. */
	public void shutDown() {
		clientThread.invoke(this::resetSidepanel);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (!"revalclan".equals(event.getGroup()) || !WATCHED_KEYS.contains(event.getKey())) {
			return;
		}
		if (anyColoringEnabled()) {
			activeTeams.refresh();
		}
		// Only the list can be repainted after the fact - chat lines are already
		// drawn, so a chat toggle takes effect from the next message onward.
		if (config.teamColorsInClanList()) {
			clientThread.invoke(this::recolorSidepanel);
		} else {
			clientThread.invoke(this::resetSidepanel);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event) {
		if (event.getType() != ChatMessageType.CLAN_CHAT || !config.teamColorsInChat()) {
			return;
		}
		activeTeams.refresh();
		Color color = activeTeams.teamColorFor(event.getName());
		if (color != null) {
			event.getMessageNode().setName(ColorUtil.wrapWithColorTag(event.getName(), chatTone(color)));
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event) {
		if (event.getScriptId() == ScriptID.CLAN_SIDEPANEL_DRAW && config.teamColorsInClanList()) {
			activeTeams.refresh();
			recolorSidepanel();
		}
	}

	private boolean anyColoringEnabled() {
		return config.teamColorsInClanList() || config.teamColorsInChat();
	}

	private void recolorSidepanel() {
		ClanSidepanel.eachNameRow(client, child -> {
			Color color = activeTeams.teamColorFor(child.getText());
			if (color != null) {
				child.setTextColor(color.getRGB() & 0xFFFFFF);
			}
		});
	}

	private void resetSidepanel() {
		ClanSidepanel.eachNameRow(client, child -> child.setTextColor(DEFAULT_NAME_COLOR));
	}

	/** Chat draws the same hex noticeably brighter than the sidepanel; deepen it there. */
	private static Color chatTone(Color color) {
		return new Color(
			Math.round(color.getRed() * 0.78f),
			Math.round(color.getGreen() * 0.78f),
			Math.round(color.getBlue() * 0.78f));
	}
}

package com.revalclan.ui;

import com.revalclan.api.RevalApiService;
import com.revalclan.api.achievements.AchievementsResponse;
import com.revalclan.ui.components.Badge;
import com.revalclan.ui.components.LoginPrompt;
import com.revalclan.ui.components.RefreshButton;
import com.revalclan.ui.constants.UIConstants;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.geom.RoundRectangle2D;
import java.util.ArrayList;
import java.util.List;

public class AchievementsPanel extends JPanel {
	private RevalApiService apiService;
	private Client client;
	private final JPanel contentPanel;
	private RefreshButton refreshBtn;
	private List<AchievementsResponse.Achievement> achievements = new ArrayList<>();

	public AchievementsPanel() {
		setLayout(new BorderLayout());
		setBackground(UIConstants.BACKGROUND);

		contentPanel = new JPanel();
		contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
		contentPanel.setBackground(UIConstants.BACKGROUND);
		contentPanel.setBorder(new EmptyBorder(8, 8, 8, 8));

		JPanel wrapper = new JPanel(new BorderLayout()) {
			@Override
			public Dimension getPreferredSize() {
				Dimension size = super.getPreferredSize();
				if (getParent() != null) size.width = getParent().getWidth();
				return size;
			}
		};
		wrapper.setBackground(UIConstants.BACKGROUND);
		wrapper.add(contentPanel, BorderLayout.NORTH);

		JScrollPane scrollPane = new JScrollPane(wrapper);
		scrollPane.setBackground(UIConstants.BACKGROUND);
		scrollPane.setBorder(null);
		scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);
		scrollPane.getViewport().setBackground(UIConstants.BACKGROUND);

		add(scrollPane, BorderLayout.CENTER);
		showNotLoggedIn();
	}

	public void init(RevalApiService apiService, Client client) {
		this.apiService = apiService;
		this.client = client;
	}

	public void onLoggedOut() {
		showNotLoggedIn();
	}

	public void refresh() {
		loadData();
	}

	private void loadData() {
		if (client == null || client.getAccountHash() == -1 || apiService == null) {
			showNotLoggedIn();
			return;
		}

		if (refreshBtn != null) refreshBtn.setLoading(true);

		apiService.fetchAchievementDefinitions(client.getAccountHash(),
			response -> SwingUtilities.invokeLater(() -> {
				if (refreshBtn != null) refreshBtn.setLoading(false);
				achievements = (response != null && response.isSuccess() && response.getData() != null)
					? response.getData().getAchievements() : new ArrayList<>();
				if (achievements == null) achievements = new ArrayList<>();
				buildUI();
			}),
			error -> SwingUtilities.invokeLater(() -> {
				if (refreshBtn != null) refreshBtn.setLoading(false);
				buildUI();
			})
		);
	}

	private void showNotLoggedIn() {
		contentPanel.removeAll();
		contentPanel.add(new LoginPrompt("Achievements"));
		contentPanel.revalidate();
		contentPanel.repaint();
	}

	private void buildUI() {
		contentPanel.removeAll();

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(UIConstants.BACKGROUND);
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));
		header.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel title = new JLabel("ACHIEVEMENTS");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(UIConstants.ACCENT_GOLD);

		refreshBtn = new RefreshButton(this::refresh);
		header.add(title, BorderLayout.WEST);
		header.add(refreshBtn, BorderLayout.EAST);

		contentPanel.add(header);
		contentPanel.add(Box.createRigidArea(new Dimension(0, 12)));

		if (achievements.isEmpty()) {
			JLabel empty = new JLabel("No achievements available");
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setForeground(UIConstants.TEXT_SECONDARY);
			empty.setAlignmentX(Component.CENTER_ALIGNMENT);
			contentPanel.add(empty);
		} else {
			JPanel grid = new JPanel(new GridLayout(0, 2, 8, 8));
			grid.setOpaque(false);
			grid.setAlignmentX(Component.LEFT_ALIGNMENT);
			for (AchievementsResponse.Achievement achievement : achievements) {
				grid.add(createCard(achievement));
			}
			contentPanel.add(grid);
		}

		contentPanel.revalidate();
		contentPanel.repaint();
	}

	private JPanel createCard(AchievementsResponse.Achievement achievement) {
		boolean completed = achievement.getProgress() != null && achievement.getProgress().isCompleted();
		Color rarityColor = getRarityColor(achievement.getRarity());

		JPanel card = new JPanel() {
			@Override
			protected void paintComponent(Graphics g) {
				super.paintComponent(g);
				Graphics2D g2d = (Graphics2D) g.create();
				g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2d.setColor(completed ? UIConstants.CARD_BG : new Color(35, 35, 40));
				g2d.fill(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), 8, 8));
				if (completed) {
					g2d.setColor(rarityColor);
					g2d.setStroke(new BasicStroke(2f));
					g2d.draw(new RoundRectangle2D.Float(1, 1, getWidth() - 2, getHeight() - 2, 8, 8));
				}
				g2d.dispose();
			}
		};

		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setOpaque(false);
		card.setBorder(new EmptyBorder(8, 8, 8, 8));
		card.setPreferredSize(new Dimension(0, 100));

		Badge badge = completed ? Badge.rarity(achievement.getRarity()) : new Badge(capitalize(achievement.getRarity()), UIConstants.TEXT_MUTED);
		badge.setAlignmentX(Component.LEFT_ALIGNMENT);

		JTextArea name = new JTextArea(achievement.getName() != null ? achievement.getName() : "Unknown");
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(completed ? rarityColor : UIConstants.TEXT_SECONDARY);
		name.setEditable(false);
		name.setFocusable(false);
		name.setLineWrap(true);
		name.setWrapStyleWord(true);
		name.setOpaque(false);
		name.setBorder(null);
		name.setMargin(new Insets(0, 0, 0, 0));
		name.setAlignmentX(Component.LEFT_ALIGNMENT);

		JTextArea desc = new JTextArea(achievement.getDescription() != null ? achievement.getDescription() : "");
		desc.setFont(FontManager.getRunescapeSmallFont());
		desc.setForeground(UIConstants.TEXT_MUTED);
		desc.setEditable(false);
		desc.setFocusable(false);
		desc.setLineWrap(true);
		desc.setWrapStyleWord(true);
		desc.setOpaque(false);
		desc.setBorder(null);
		desc.setMargin(new Insets(0, 0, 0, 0));
		desc.setAlignmentX(Component.LEFT_ALIGNMENT);

		card.add(badge);
		card.add(Box.createRigidArea(new Dimension(0, 3)));
		card.add(name);
		card.add(Box.createRigidArea(new Dimension(0, 3)));
		card.add(desc);

		return card;
	}

	private Color getRarityColor(String rarity) {
		if (rarity == null) return UIConstants.RARITY_COMMON;
		switch (rarity.toLowerCase()) {
			case "uncommon": return UIConstants.RARITY_UNCOMMON;
			case "rare": return UIConstants.RARITY_RARE;
			case "epic": return UIConstants.RARITY_EPIC;
			case "legendary": return UIConstants.RARITY_LEGENDARY;
			case "mythic": return UIConstants.RARITY_MYTHIC;
			default: return UIConstants.RARITY_COMMON;
		}
	}

	private String capitalize(String s) {
		if (s == null || s.isEmpty()) return "Unknown";
		return s.substring(0, 1).toUpperCase() + s.substring(1).toLowerCase();
	}
}

package com.revalclan.ui;

import com.revalclan.api.RevalApiService;
import com.revalclan.api.competitions.*;
import com.revalclan.ui.components.BackButton;
import com.revalclan.ui.components.Clickable;
import com.revalclan.ui.components.PanelTitle;
import com.revalclan.ui.components.RefreshButton;
import com.revalclan.ui.components.ScrollWrap;
import com.revalclan.ui.constants.UIConstants;
import com.revalclan.util.DateTimeUtil;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;

import com.revalclan.ui.components.LoginPrompt;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class CompetitionsPanel extends JPanel {
	private static final Color MEDAL_GOLD = new Color(255, 215, 0);
	private static final Color MEDAL_SILVER = new Color(198, 198, 198);
	private static final Color MEDAL_BRONZE = new Color(205, 127, 80);

	private RevalApiService apiService;
	private Client client;
	private RefreshButton refreshButton;

	private final CardLayout cardLayout;
	private final JPanel cardContainer;
	private final JPanel contentPanel;
	private final JPanel detailViewPanel;

	private List<VotesResponse.Vote> activeVotes = new ArrayList<>();
	private List<CompetitionsResponse.Competition> activeCompetitions = new ArrayList<>();
	private List<CompetitionsResponse.Competition> scheduledCompetitions = new ArrayList<>();
	private Map<String, String> myVotes = new HashMap<>();

	private int loadGeneration;

	public CompetitionsPanel() {
		setLayout(new BorderLayout());
		setBackground(UIConstants.BACKGROUND);

		cardLayout = new CardLayout();
		cardContainer = new JPanel(cardLayout);
		cardContainer.setBackground(UIConstants.BACKGROUND);

		// List view
		JPanel listViewPanel = new JPanel(new BorderLayout());
		listViewPanel.setBackground(UIConstants.BACKGROUND);
		listViewPanel.add(createHeader(), BorderLayout.NORTH);

		contentPanel = new JPanel();
		contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
		contentPanel.setBackground(UIConstants.BACKGROUND);
		contentPanel.setBorder(new EmptyBorder(8, 8, 8, 8));

		listViewPanel.add(ScrollWrap.of(contentPanel), BorderLayout.CENTER);

		// Detail view
		detailViewPanel = new JPanel(new BorderLayout());
		detailViewPanel.setBackground(UIConstants.BACKGROUND);

		cardContainer.add(listViewPanel, "LIST");
		cardContainer.add(detailViewPanel, "DETAIL");
		add(cardContainer, BorderLayout.CENTER);
	}

	private JPanel createHeader() {
		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(UIConstants.CARD_BG);
		header.setBorder(new EmptyBorder(10, 12, 10, 12));
		header.add(new PanelTitle("Competitions", UIConstants.TEXT_PRIMARY), BorderLayout.WEST);
		refreshButton = new RefreshButton(this::refresh);
		header.add(refreshButton, BorderLayout.EAST);
		return header;
	}

	public void init(RevalApiService apiService, Client client) {
		this.apiService = apiService;
		this.client = client;
	}

	public void onLoggedOut() {
		loadGeneration++;
		myVotes.clear();
		activeVotes = new ArrayList<>();
		activeCompetitions = new ArrayList<>();
		scheduledCompetitions = new ArrayList<>();
		refreshButton.setLoading(false);
		cardLayout.show(cardContainer, "LIST");
		contentPanel.removeAll();
		contentPanel.add(new LoginPrompt("Competitions"));
		contentPanel.revalidate();
		contentPanel.repaint();
	}

	public void refresh() {
		loadData(false);
	}

	private void loadData(boolean showLoadingState) {
		if (apiService == null) return;
		if (client == null || client.getAccountHash() == -1) {
			onLoggedOut();
			return;
		}
		final int generation = ++loadGeneration;
		if (showLoadingState) showLoading();
		refreshButton.setLoading(true);

		final boolean[] loaded = {false, false, false};
		Runnable checkComplete = () -> {
			if (loaded[0] && loaded[1] && loaded[2]) {
				refreshButton.setLoading(false);
				buildContent();
			}
		};

		apiService.fetchVotes(
			response -> SwingUtilities.invokeLater(() -> {
				if (generation != loadGeneration) return;
				activeVotes = response.getData() != null && response.getData().getVotes() != null
					? response.getData().getVotes() : new ArrayList<>();
				fetchMyVotes(activeVotes, generation);
				loaded[0] = true;
				checkComplete.run();
			}),
			error -> SwingUtilities.invokeLater(() -> {
				if (generation != loadGeneration) return;
				activeVotes = new ArrayList<>();
				loaded[0] = true;
				checkComplete.run();
			})
		);

		apiService.fetchActiveCompetitions(
			response -> SwingUtilities.invokeLater(() -> {
				if (generation != loadGeneration) return;
				activeCompetitions = response.getData() != null && response.getData().getCompetitions() != null
					? response.getData().getCompetitions() : new ArrayList<>();
				loaded[1] = true;
				checkComplete.run();
			}),
			error -> SwingUtilities.invokeLater(() -> {
				if (generation != loadGeneration) return;
				activeCompetitions = new ArrayList<>();
				loaded[1] = true;
				checkComplete.run();
			})
		);

		apiService.fetchScheduledCompetitions(
			response -> SwingUtilities.invokeLater(() -> {
				if (generation != loadGeneration) return;
				scheduledCompetitions = response.getData() != null && response.getData().getCompetitions() != null
					? response.getData().getCompetitions() : new ArrayList<>();
				loaded[2] = true;
				checkComplete.run();
			}),
			error -> SwingUtilities.invokeLater(() -> {
				if (generation != loadGeneration) return;
				scheduledCompetitions = new ArrayList<>();
				loaded[2] = true;
				checkComplete.run();
			})
		);
	}

	private void fetchMyVotes(List<VotesResponse.Vote> votes, int generation) {
		if (client == null || client.getAccountHash() == -1) return;
		myVotes.clear();
		for (VotesResponse.Vote vote : votes) {
			apiService.fetchMyVote(vote.getId(), client.getAccountHash(),
				response -> SwingUtilities.invokeLater(() -> {
					if (generation != loadGeneration) return;
					if (response.getData() != null && response.getData().getHasVoted() && response.getData().getOptionId() != null) {
						myVotes.put(vote.getId(), response.getData().getOptionId());
						buildContent();
					}
				}),
				error -> {}
			);
		}
	}

	private void showLoading() {
		contentPanel.removeAll();
		contentPanel.add(Box.createVerticalStrut(30));
		contentPanel.add(label("Loading competitions...", FontManager.getRunescapeSmallFont(), UIConstants.TEXT_SECONDARY, Component.CENTER_ALIGNMENT));
		contentPanel.revalidate();
		contentPanel.repaint();
	}

	private void buildContent() {
		contentPanel.removeAll();
		boolean hasContent = false;

		if (!activeVotes.isEmpty()) {
			hasContent = true;
			addSection("Active Votes");
			for (VotesResponse.Vote vote : activeVotes) {
				contentPanel.add(createVoteCard(vote));
				contentPanel.add(Box.createVerticalStrut(8));
			}
			contentPanel.add(Box.createVerticalStrut(12));
		}

		if (!activeCompetitions.isEmpty()) {
			hasContent = true;
			addSection("Active Competitions");
			for (CompetitionsResponse.Competition comp : activeCompetitions) {
				contentPanel.add(createCompetitionCard(comp, true));
				contentPanel.add(Box.createVerticalStrut(8));
			}
			contentPanel.add(Box.createVerticalStrut(12));
		}

		if (!scheduledCompetitions.isEmpty()) {
			hasContent = true;
			addSection("Upcoming Competitions");
			for (CompetitionsResponse.Competition comp : scheduledCompetitions) {
				contentPanel.add(createCompetitionCard(comp, false));
				contentPanel.add(Box.createVerticalStrut(8));
			}
		}

		if (!hasContent) {
			contentPanel.add(Box.createVerticalStrut(30));
			contentPanel.add(label("No active competitions or votes", FontManager.getRunescapeSmallFont(), UIConstants.TEXT_SECONDARY, Component.CENTER_ALIGNMENT));
		}

		contentPanel.revalidate();
		contentPanel.repaint();


	}

	private void addSection(String text) {
		contentPanel.add(label(text, FontManager.getRunescapeBoldFont(), UIConstants.TEXT_PRIMARY));
		contentPanel.add(Box.createVerticalStrut(6));
	}

	private JPanel createVoteCard(VotesResponse.Vote vote) {
		JPanel card = createCard();

		card.add(label(vote.getTitle(), FontManager.getRunescapeBoldFont(), UIConstants.ACCENT_GOLD));
		if (vote.getDescription() != null && !vote.getDescription().isEmpty()) {
			card.add(Box.createVerticalStrut(4));
			card.add(label(vote.getDescription(), FontManager.getRunescapeSmallFont(), UIConstants.TEXT_SECONDARY));
		}

		card.add(Box.createVerticalStrut(6));
		card.add(label("Ends in " + formatTimeRemaining(vote.getVoteEndDate()), FontManager.getRunescapeSmallFont(), UIConstants.TEXT_MUTED));
		card.add(label(vote.getTotalVotes() + " total votes", FontManager.getRunescapeSmallFont(), UIConstants.TEXT_MUTED));

		if (vote.getOptions() != null && !vote.getOptions().isEmpty()) {
			card.add(Box.createVerticalStrut(10));
			String myVotedId = myVotes.get(vote.getId());
			for (VotesResponse.VoteOption option : vote.getOptions()) {
				boolean isMyVote = option.getId() != null && option.getId().equals(myVotedId);
				card.add(createVoteOptionRow(vote, option, isMyVote));
				card.add(Box.createVerticalStrut(4));
			}
		}

		return roundedWrapper(card);
	}

	private JPanel createVoteOptionRow(VotesResponse.Vote vote, VotesResponse.VoteOption option, boolean isMyVote) {
		Color selectedBg = new Color(UIConstants.ACCENT_BLUE.getRed(), UIConstants.ACCENT_BLUE.getGreen(), UIConstants.ACCENT_BLUE.getBlue(), 40);
		Color defaultBg = isMyVote ? selectedBg : UIConstants.BACKGROUND;

		JPanel row = roundedPanel(defaultBg, isMyVote ? UIConstants.ACCENT_BLUE : null);
		row.setLayout(new BorderLayout(8, 0));
		row.setBorder(new EmptyBorder(8, 10, 8, 10));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		row.add(label(option.getTemplateName(), FontManager.getRunescapeSmallFont(),
			isMyVote ? UIConstants.ACCENT_BLUE : UIConstants.TEXT_PRIMARY, -1), BorderLayout.WEST);

		int pct = vote.getTotalVotes() > 0 ? (int) Math.round((option.getVoteCount() * 100.0) / vote.getTotalVotes()) : 0;
		row.add(label(option.getVoteCount() + " (" + pct + "%)", FontManager.getRunescapeSmallFont(),
			UIConstants.ACCENT_BLUE, -1), BorderLayout.EAST);

		Clickable.onPress(row, () -> castVote(vote.getId(), option.getId()), UIConstants.CARD_HOVER, defaultBg);

		return row;
	}

	private void castVote(String voteId, String optionId) {
		if (apiService == null || client == null || client.getAccountHash() == -1) {
			JOptionPane.showMessageDialog(this, "Please log in to vote", "Not Logged In", JOptionPane.WARNING_MESSAGE);
			return;
		}

		apiService.castVote(voteId, optionId, client.getAccountHash(),
			response -> SwingUtilities.invokeLater(() -> {
				String msg = response.getData() != null && response.getData().getPreviousOptionId() != null
					? "Vote changed!" : "Vote cast!";
				JOptionPane.showMessageDialog(this, msg, "Voted", JOptionPane.INFORMATION_MESSAGE);
				refresh();
			}),
			error -> SwingUtilities.invokeLater(() ->
				JOptionPane.showMessageDialog(this, "Failed: " + error.getMessage(), "Error", JOptionPane.ERROR_MESSAGE))
		);
	}

	private JPanel createCompetitionCard(CompetitionsResponse.Competition comp, boolean isActive) {
		JPanel card = createCard();
		card.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		card.add(label(comp.getName(), FontManager.getRunescapeBoldFont(), isActive ? UIConstants.ACCENT_GREEN : UIConstants.TEXT_PRIMARY));
		if (comp.getDescription() != null && !comp.getDescription().isEmpty()) {
			card.add(Box.createVerticalStrut(4));
			card.add(label(comp.getDescription(), FontManager.getRunescapeSmallFont(), UIConstants.TEXT_SECONDARY));
		}

		card.add(Box.createVerticalStrut(6));
		String timeText = isActive ? "Ends in " + formatTimeRemaining(comp.getEndDate())
			: "Starts in " + formatTimeRemaining(comp.getStartDate());
		card.add(label(timeText, FontManager.getRunescapeFont(), isActive ? UIConstants.ACCENT_GREEN : UIConstants.TEXT_PRIMARY));

		if (comp.getParticipantCount() != null && comp.getParticipantCount() > 0) {
			card.add(label(comp.getParticipantCount() + " participants", FontManager.getRunescapeSmallFont(), UIConstants.TEXT_MUTED));
		}

		if (isActive && comp.getLeaderboard() != null && !comp.getLeaderboard().isEmpty()) {
			card.add(Box.createVerticalStrut(8));
			card.add(createLeaderboardPreview(comp.getLeaderboard(), comp.getCompetitionType()));
		}

		if (comp.getRewardConfig() != null && !comp.getRewardConfig().isEmpty()) {
			card.add(Box.createVerticalStrut(8));
			JSeparator divider = new JSeparator(SwingConstants.HORIZONTAL);
			divider.setForeground(UIConstants.BACKGROUND);
			divider.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
			divider.setAlignmentX(Component.LEFT_ALIGNMENT);
			card.add(divider);
			card.add(Box.createVerticalStrut(8));
			card.add(label("PRIZES", FontManager.getRunescapeSmallFont(), UIConstants.TEXT_MUTED));
			card.add(Box.createVerticalStrut(4));
			card.add(createRewardsGrid(comp.getRewardConfig()));
		}

		Clickable.onPress(card, () -> showCompetitionDetails(comp), UIConstants.CARD_HOVER, UIConstants.CARD_BG);

		return roundedWrapper(card);
	}

	private JPanel createLeaderboardPreview(List<CompetitionsResponse.LeaderboardEntry> leaderboard, String type) {
		JPanel preview = new JPanel();
		preview.setLayout(new BoxLayout(preview, BoxLayout.Y_AXIS));
		preview.setOpaque(false);
		preview.setAlignmentX(Component.LEFT_ALIGNMENT);

		String suffix = getValueSuffix(type);
		for (int i = 0; i < Math.min(3, leaderboard.size()); i++) {
			CompetitionsResponse.LeaderboardEntry entry = leaderboard.get(i);
			Integer value = entry.getCurrentValue() != null ? entry.getCurrentValue() : entry.getFinalValue();

			JPanel row = new JPanel(new BorderLayout());
			row.setOpaque(false);
			row.setAlignmentX(Component.LEFT_ALIGNMENT);
			row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));

			JPanel nameCell = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
			nameCell.setOpaque(false);
			Color placeColor = i == 0 ? MEDAL_GOLD : i == 1 ? MEDAL_SILVER : MEDAL_BRONZE;
			nameCell.add(label((i + 1) + ". ", FontManager.getRunescapeSmallFont(), placeColor, -1));
			nameCell.add(label(entry.getOsrsNickname(), FontManager.getRunescapeSmallFont(), UIConstants.TEXT_PRIMARY, -1));
			row.add(nameCell, BorderLayout.WEST);
			row.add(label(value != null ? formatValue(value) + suffix : "-", FontManager.getRunescapeBoldFont(), UIConstants.ACCENT_BLUE, -1), BorderLayout.EAST);
			preview.add(row);
		}

		return preview;
	}

	private void showCompetitionDetails(CompetitionsResponse.Competition comp) {
		detailViewPanel.removeAll();

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(UIConstants.CARD_BG);
		header.setBorder(new EmptyBorder(8, 10, 8, 10));
		header.add(new BackButton("< Back", this::showListView), BorderLayout.WEST);
		header.add(label(comp.getName(), FontManager.getRunescapeBoldFont(), UIConstants.ACCENT_GOLD, -1), BorderLayout.EAST);
		detailViewPanel.add(header, BorderLayout.NORTH);

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(UIConstants.BACKGROUND);
		content.setBorder(new EmptyBorder(12, 12, 12, 12));
		content.add(Box.createVerticalStrut(20));
		content.add(label("Loading leaderboard...", FontManager.getRunescapeSmallFont(), UIConstants.TEXT_SECONDARY, Component.CENTER_ALIGNMENT));

		detailViewPanel.add(ScrollWrap.of(content), BorderLayout.CENTER);
		detailViewPanel.revalidate();
		detailViewPanel.repaint();
		cardLayout.show(cardContainer, "DETAIL");

		apiService.fetchCompetitionDetails(comp.getId(),
			response -> SwingUtilities.invokeLater(() -> buildDetailsContent(content, response.getData())),
			error -> SwingUtilities.invokeLater(() -> {
				content.removeAll();
				content.add(Box.createVerticalStrut(20));
				content.add(label("Failed to load: " + error.getMessage(), FontManager.getRunescapeSmallFont(), UIConstants.ERROR_COLOR, Component.CENTER_ALIGNMENT));
				content.revalidate();
				content.repaint();
			})
		);
	}

	private void buildDetailsContent(JPanel content, CompetitionsResponse.Competition comp) {
		content.removeAll();

		if (comp == null) {
			content.add(label("Competition not found", FontManager.getRunescapeSmallFont(), UIConstants.ERROR_COLOR, Component.CENTER_ALIGNMENT));
			content.revalidate();
			content.repaint();
			return;
		}

		if (comp.getDescription() != null) {
			content.add(label(comp.getDescription(), FontManager.getRunescapeSmallFont(), UIConstants.TEXT_SECONDARY));
			content.add(Box.createVerticalStrut(8));
		}

		boolean isActive = "active".equalsIgnoreCase(comp.getStatus());
		String timeText = isActive ? "Ends in " + formatTimeRemaining(comp.getEndDate())
			: "Starts in " + formatTimeRemaining(comp.getStartDate());
		content.add(label(timeText, FontManager.getRunescapeFont(), UIConstants.TEXT_PRIMARY));

		if (comp.getParticipantCount() != null) {
			content.add(label(comp.getParticipantCount() + " participants", FontManager.getRunescapeSmallFont(), UIConstants.TEXT_MUTED));
		}

		content.add(Box.createVerticalStrut(12));
		content.add(label("Leaderboard", FontManager.getRunescapeBoldFont(), UIConstants.TEXT_PRIMARY));
		content.add(Box.createVerticalStrut(6));

		if (comp.getLeaderboard() != null && !comp.getLeaderboard().isEmpty()) {
			for (int i = 0; i < comp.getLeaderboard().size(); i++) {
				content.add(createLeaderboardRow(comp.getLeaderboard().get(i), i + 1, comp.getCompetitionType()));
				content.add(Box.createVerticalStrut(2));
			}
		} else {
			content.add(label("No participants yet", FontManager.getRunescapeSmallFont(), UIConstants.TEXT_MUTED));
		}

		if (comp.getSideQuests() != null && !comp.getSideQuests().isEmpty()) {
			content.add(Box.createVerticalStrut(16));
			content.add(label("Side Quests", FontManager.getRunescapeBoldFont(), UIConstants.TEXT_PRIMARY));
			content.add(Box.createVerticalStrut(6));
			for (CompetitionsResponse.SideQuest sq : comp.getSideQuests()) {
				content.add(createSideQuestCard(sq));
				content.add(Box.createVerticalStrut(8));
			}
		}

		content.revalidate();
		content.repaint();
	}

	private JPanel createLeaderboardRow(CompetitionsResponse.LeaderboardEntry entry, int rank, String type) {
		String playerName = client != null && client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
		boolean isCurrentPlayer = playerName != null && entry.getOsrsNickname() != null
			&& entry.getOsrsNickname().equalsIgnoreCase(playerName);

		JPanel row = roundedPanel(UIConstants.CARD_BG, isCurrentPlayer ? UIConstants.ACCENT_BLUE : null);
		row.setLayout(new BorderLayout(4, 0));
		row.setBorder(new EmptyBorder(6, 10, 6, 10));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));

		Color rankColor = rank == 1 ? MEDAL_GOLD
			: rank == 2 ? MEDAL_SILVER
			: rank == 3 ? MEDAL_BRONZE
			: UIConstants.TEXT_SECONDARY;

		JLabel rankLabel = label("#" + rank, FontManager.getRunescapeBoldFont(), rankColor, -1);
		rankLabel.setPreferredSize(new Dimension(42, 20));

		Integer value = entry.getCurrentValue() != null ? entry.getCurrentValue() : entry.getFinalValue();

		row.add(rankLabel, BorderLayout.WEST);
		row.add(label(entry.getOsrsNickname(), FontManager.getRunescapeSmallFont(),
			isCurrentPlayer ? UIConstants.ACCENT_BLUE : UIConstants.TEXT_PRIMARY, -1), BorderLayout.CENTER);
		row.add(label(value != null ? formatValue(value) + getValueSuffix(type) : "-", FontManager.getRunescapeBoldFont(), UIConstants.ACCENT_GOLD, -1), BorderLayout.EAST);

		return row;
	}

	private JPanel createSideQuestCard(CompetitionsResponse.SideQuest sq) {
		JPanel card = createCard();
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, 120));

		card.add(label(sq.getName(), FontManager.getRunescapeBoldFont(), UIConstants.ACCENT_PURPLE));
		if (sq.getDescription() != null) {
			card.add(label(sq.getDescription(), FontManager.getRunescapeSmallFont(), UIConstants.TEXT_SECONDARY));
		}

		if (sq.getLeaderboard() != null && !sq.getLeaderboard().isEmpty()) {
			card.add(Box.createVerticalStrut(6));
			String suffix = getValueSuffix(sq.getSideQuestType());
			for (int i = 0; i < Math.min(3, sq.getLeaderboard().size()); i++) {
				CompetitionsResponse.LeaderboardEntry entry = sq.getLeaderboard().get(i);
				card.add(label((i + 1) + ". " + entry.getOsrsNickname() + " - " + formatValue(entry.getCurrentValue()) + suffix,
					FontManager.getRunescapeSmallFont(), UIConstants.TEXT_PRIMARY));
			}
		}

		return roundedWrapper(card);
	}

	private void showListView() {
		cardLayout.show(cardContainer, "LIST");
	}

	// ── UI Helpers ──────────────────────────────────────────────────────

	/** Creates a left-aligned JLabel. */
	private JLabel label(String text, Font font, Color color) {
		return label(text, font, color, Component.LEFT_ALIGNMENT);
	}

	/** Creates a JLabel with optional alignment (-1 to skip alignment). */
	private JLabel label(String text, Font font, Color color, float alignment) {
		JLabel l = new JLabel(text);
		l.setFont(font);
		l.setForeground(color);
		if (alignment >= 0) l.setAlignmentX(alignment);
		return l;
	}

	/** Creates a card panel with BoxLayout.Y_AXIS. */
	private JPanel createCard() {
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(UIConstants.CARD_BG);
		card.setBorder(new EmptyBorder(12, 14, 12, 14));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, 300));
		return card;
	}

	/** Creates a non-opaque JPanel with rounded paintComponent and optional border. */
	private JPanel roundedPanel(Color bg, Color borderColor) {
		JPanel panel = new JPanel() {
			@Override
			protected void paintComponent(Graphics g) {
				Graphics2D g2d = (Graphics2D) g.create();
				g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2d.setColor(getBackground());
				g2d.fillRoundRect(0, 0, getWidth(), getHeight(), 4, 4);
				if (borderColor != null) {
					g2d.setColor(borderColor);
					g2d.setStroke(new BasicStroke(2));
					g2d.drawRoundRect(1, 1, getWidth() - 3, getHeight() - 3, 4, 4);
				}
				g2d.dispose();
			}
		};
		panel.setOpaque(false);
		panel.setBackground(bg);
		return panel;
	}

	/** Wraps an inner card panel with a rounded-corner outer wrapper. */
	private JPanel roundedWrapper(JPanel inner) {
		JPanel wrapper = new JPanel(new BorderLayout()) {
			@Override
			protected void paintComponent(Graphics g) {
				Graphics2D g2d = (Graphics2D) g.create();
				g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2d.setColor(inner.getBackground());
				g2d.fillRoundRect(0, 0, getWidth(), getHeight(), 8, 8);
				g2d.dispose();
			}
		};
		wrapper.setOpaque(false);
		wrapper.add(inner, BorderLayout.CENTER);
		wrapper.setAlignmentX(Component.LEFT_ALIGNMENT);
		wrapper.setMaximumSize(inner.getMaximumSize());
		return wrapper;
	}

	/** Wraps a content panel in a scroll pane pinned to the top. */

	// ── Formatting ──────────────────────────────────────────────────────

	private String formatTimeRemaining(String dateStr) {
		if (dateStr == null) return "Unknown";
		try {
			Instant target = DateTimeUtil.parseToInstant(dateStr);
			Instant now = Instant.now();
			long days = ChronoUnit.DAYS.between(now, target);
			long hours = ChronoUnit.HOURS.between(now, target) % 24;
			if (days < 0 || (days == 0 && hours < 0)) return "Ended";
			if (days > 0) return days + "d " + hours + "h";
			return hours + "h " + (ChronoUnit.MINUTES.between(now, target) % 60) + "m";
		} catch (Exception e) {
			return dateStr;
		}
	}

	/** Prize breakdown rows: place on the left, points on the right */
	private JPanel createRewardsGrid(Map<String, Integer> rewards) {
		JPanel grid = new JPanel(new GridLayout(0, 1, 0, 3));
		grid.setOpaque(false);
		grid.setAlignmentX(Component.LEFT_ALIGNMENT);

		addRewardCell(grid, "1st", rewards.get("1"), MEDAL_GOLD);
		addRewardCell(grid, "2nd", rewards.get("2"), MEDAL_SILVER);
		addRewardCell(grid, "3rd", rewards.get("3"), MEDAL_BRONZE);
		addRewardCell(grid, "4-10th", rewards.get("top10"), UIConstants.TEXT_SECONDARY);

		grid.setMaximumSize(new Dimension(Integer.MAX_VALUE, grid.getPreferredSize().height));
		return grid;
	}

	private void addRewardCell(JPanel grid, String place, Integer points, Color placeColor) {
		if (points == null) return;

		JPanel cell = new JPanel(new BorderLayout());
		cell.setOpaque(false);

		JLabel placeLabel = new JLabel(place);
		placeLabel.setFont(FontManager.getRunescapeSmallFont());
		placeLabel.setForeground(placeColor);

		JLabel pointsLabel = new JLabel(points + " pts");
		pointsLabel.setFont(FontManager.getRunescapeSmallFont());
		pointsLabel.setForeground(UIConstants.ACCENT_GOLD);

		cell.add(placeLabel, BorderLayout.WEST);
		cell.add(pointsLabel, BorderLayout.EAST);
		grid.add(cell);
	}

	private String formatValue(Integer value) {
		if (value == null) return "-";
		if (value >= 1_000_000) return String.format("%.1fM", value / 1_000_000.0);
		if (value >= 1_000) return String.format("%.1fK", value / 1_000.0);
		return String.valueOf(value);
	}

	private String getValueSuffix(String type) {
		if (type == null) return "";
		String t = type.toLowerCase();
		if (t.contains("xp") || t.contains("experience") || t.contains("skill")) return " XP";
		if (t.contains("kc") || t.contains("kill") || t.contains("boss") || t.contains("npc")) return " KC";
		return "";
	}
}

package com.revalclan.ui;

