package com.revalclan.ui.components;

import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;

/**
 * Click wiring for custom clickable panels and labels. Actions fire on
 * mousePressed, never mouseClicked: a trackpad micro-drag between press
 * and release makes Swing drop mouseClicked entirely.
 */
public final class Clickable {
	private Clickable() {
	}

	/** Left-click action; also sets the hand cursor. */
	public static void onPress(JComponent component, Runnable action) {
		component.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		component.addMouseListener(new MouseAdapter() {
			@Override
			public void mousePressed(MouseEvent e) {
				if (SwingUtilities.isLeftMouseButton(e)) {
					action.run();
				}
			}
		});
	}

	/** Left-click action with a background swap on hover. */
	public static void onPress(JComponent component, Runnable action, Color hoverBg, Color restingBg) {
		component.addMouseListener(new MouseAdapter() {
			@Override
			public void mouseEntered(MouseEvent e) {
				component.setBackground(hoverBg);
			}

			@Override
			public void mouseExited(MouseEvent e) {
				component.setBackground(restingBg);
			}
		});
		onPress(component, action);
	}

	/** Left-click action with a hover flag for custom-painted components; repaints on change. */
	public static void onPress(JComponent component, Runnable action, Consumer<Boolean> hovered) {
		component.addMouseListener(new MouseAdapter() {
			@Override
			public void mouseEntered(MouseEvent e) {
				hovered.accept(true);
				component.repaint();
			}

			@Override
			public void mouseExited(MouseEvent e) {
				hovered.accept(false);
				component.repaint();
			}
		});
		onPress(component, action);
	}
}

package com.revalclan.ui.components;

import com.revalclan.ui.constants.UIConstants;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

public class CollapsibleSection extends JPanel {
	private final JPanel contentPanel;
	private final JLabel arrowLabel;
	private final JLabel iconLabel;
	private final JPanel headerPanel;
	private boolean expanded;

	public CollapsibleSection(String title, String subtitle, JPanel content, boolean startExpanded) {
		setLayout(new BorderLayout());
		setBackground(UIConstants.BACKGROUND);
		setBorder(new EmptyBorder(0, 0, 3, 0));

		this.expanded = startExpanded;
		this.contentPanel = content;
		contentPanel.setVisible(expanded);

		headerPanel = new JPanel(new BorderLayout(2, 0)) {
			@Override
			protected void paintComponent(Graphics g) {
				Graphics2D g2d = (Graphics2D) g.create();
				g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2d.setColor(getBackground());
				g2d.fillRoundRect(0, 0, getWidth(), getHeight(), 6, 6);
				g2d.dispose();
			}
		};
		headerPanel.setBackground(UIConstants.HEADER_BG);
		headerPanel.setBorder(new EmptyBorder(6, 8, 6, 8));
		headerPanel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		headerPanel.setOpaque(false);

		JPanel leftPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		leftPanel.setOpaque(false);

		arrowLabel = new JLabel(new TriangleIcon(expanded, 9, UIConstants.ACCENT_GOLD));
		leftPanel.add(arrowLabel);

		iconLabel = new JLabel();
		iconLabel.setPreferredSize(new Dimension(24, 24));
		leftPanel.add(iconLabel);

		JPanel titlePanel = new JPanel();
		titlePanel.setOpaque(false);

		JLabel titleLabel = new JLabel(title);
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setForeground(UIConstants.TEXT_PRIMARY);

		if (subtitle != null && !subtitle.isEmpty()) {
			titlePanel.setLayout(new BoxLayout(titlePanel, BoxLayout.Y_AXIS));
			titleLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
			titlePanel.add(titleLabel);

			JLabel subtitleLabel = new JLabel(subtitle);
			subtitleLabel.setFont(FontManager.getRunescapeSmallFont());
			subtitleLabel.setForeground(UIConstants.TEXT_SECONDARY);
			subtitleLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
			titlePanel.add(subtitleLabel);
		} else {
			titlePanel.setLayout(new BorderLayout());
			titlePanel.add(titleLabel, BorderLayout.CENTER);
		}

		headerPanel.add(leftPanel, BorderLayout.WEST);
		headerPanel.add(titlePanel, BorderLayout.CENTER);

		Clickable.onPress(headerPanel, () -> setExpanded(!expanded), UIConstants.HEADER_HOVER, UIConstants.HEADER_BG);

		add(headerPanel, BorderLayout.NORTH);
		add(contentPanel, BorderLayout.CENTER);
	}

	public void setIcon(Icon icon) {
		iconLabel.setIcon(icon);
	}

	public void setExpanded(boolean expanded) {
		this.expanded = expanded;
		arrowLabel.setIcon(new TriangleIcon(expanded, 9, UIConstants.ACCENT_GOLD));
		contentPanel.setVisible(expanded);
		revalidate();
	}

	public boolean isExpanded() {
		return expanded;
	}
}

