package com.revalclan.ui.components;

import com.revalclan.api.points.PointsResponse;
import com.revalclan.ui.constants.UIConstants;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

public class PointSourceCard extends JPanel {
	private final JLabel iconLabel = new JLabel();
	private Color pointsColor = UIConstants.ACCENT_GREEN;

	public PointSourceCard(PointsResponse.PointSource source, ItemManager itemManager) {
		Integer itemId = source.getMetadata() != null ? source.getMetadata().getItemId() : null;
		init(source.getName(), source.getDescription(), source.getPointsDisplay(), itemId, itemManager);
	}

	public PointSourceCard(String name, String description, String points, ItemManager itemManager) {
		init(name, description, points, null, itemManager);
	}

	public static PointSourceCard forUntradeable(PointsResponse.PointSource source, ItemManager itemManager) {
		Integer itemId = source.getMetadata() != null ? source.getMetadata().getItemId() : null;
		String subtitle = source.getMetadata() != null ? source.getMetadata().getSource() : null;
		PointSourceCard card = new PointSourceCard();
		card.init(source.getName(), subtitle, source.getPointsDisplay(), itemId, itemManager);
		return card;
	}

	private PointSourceCard() {}

	private void init(String name, String description, String points, Integer itemId, ItemManager itemManager) {
		setLayout(new BorderLayout(4, 0));
		setBackground(UIConstants.ROW_BG);
		setBorder(new EmptyBorder(5, 8, 5, 8));
		setToolTipText(name);

		boolean hasIcon = itemId != null && itemManager != null;

		JPanel leftPanel = new JPanel(new BorderLayout(hasIcon ? 6 : 0, 0));
		leftPanel.setOpaque(false);

		if (hasIcon) {
			iconLabel.setPreferredSize(new Dimension(24, 24));
			leftPanel.add(iconLabel, BorderLayout.WEST);
			loadIcon(itemId, itemManager);
		}

		JPanel textPanel = new JPanel();
		textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));
		textPanel.setOpaque(false);

		JLabel nameLabel = new JLabel(name);
		nameLabel.setFont(FontManager.getRunescapeBoldFont());
		nameLabel.setForeground(UIConstants.TEXT_PRIMARY);
		nameLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		textPanel.add(nameLabel);

		if (description != null && !description.isEmpty()) {
			JTextArea descArea = new JTextArea(description);
			descArea.setFont(FontManager.getRunescapeSmallFont());
			descArea.setForeground(UIConstants.TEXT_SECONDARY);
			descArea.setEditable(false);
			descArea.setFocusable(false);
			descArea.setLineWrap(true);
			descArea.setWrapStyleWord(true);
			descArea.setOpaque(false);
			descArea.setBorder(null);
			descArea.setAlignmentX(Component.LEFT_ALIGNMENT);
			textPanel.add(descArea);
		}

		leftPanel.add(textPanel, BorderLayout.CENTER);

		JLabel pointsLabel = new JLabel(points);
		pointsLabel.setFont(FontManager.getRunescapeSmallFont());
		pointsLabel.setForeground(pointsColor);
		pointsLabel.setVerticalAlignment(SwingConstants.TOP);

		add(leftPanel, BorderLayout.CENTER);
		add(pointsLabel, BorderLayout.EAST);
	}

	private void loadIcon(int itemId, ItemManager itemManager) {
		try {
			AsyncBufferedImage img = itemManager.getImage(itemId);
			img.onLoaded(() -> SwingUtilities.invokeLater(() -> 
				iconLabel.setIcon(new ImageIcon(ImageUtil.resizeImage(img, 24, 24)))
			));
		} catch (Exception ignored) {}
	}

	@Override
	protected void paintComponent(Graphics g) {
		Graphics2D g2d = (Graphics2D) g.create();
		g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2d.setColor(getBackground());
		g2d.fillRoundRect(0, 0, getWidth(), getHeight(), 4, 4);
		g2d.dispose();
	}
}

package com.revalclan.ui.components;

import com.revalclan.ui.constants.UIConstants;

import javax.swing.JComponent;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;

/** Thin rounded progress bar that stretches to its container's width. */
public class ProgressBar extends JComponent {
	private static final int HEIGHT = 6;
	private final int percent;
	private final Color color;

	public ProgressBar(int percent, Color color) {
		this.percent = Math.max(0, Math.min(100, percent));
		this.color = color;
		setPreferredSize(new Dimension(100, HEIGHT));
		setMinimumSize(new Dimension(20, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
		setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics g) {
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(UIConstants.PROGRESS_BG);
		g2.fillRoundRect(0, 0, getWidth(), getHeight(), HEIGHT, HEIGHT);
		int w = (int) Math.round(getWidth() * percent / 100d);
		if (w > 0) {
			g2.setColor(color);
			g2.fillRoundRect(0, 0, Math.max(w, HEIGHT), getHeight(), HEIGHT, HEIGHT);
		}
		g2.dispose();
	}
}

package com.revalclan.ui.components;

import com.revalclan.api.points.PointsResponse;
import com.revalclan.ui.constants.UIConstants;
import com.revalclan.util.ClanRankIconResolver;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

public class RankCard extends JPanel {
	private final JLabel iconLabel = new JLabel();

	public RankCard(PointsResponse.Rank rank, ClanRankIconResolver iconResolver) {
		setLayout(new BorderLayout(6, 0));
		setBackground(UIConstants.CARD_BG);
		setBorder(new EmptyBorder(8, 6, 8, 10));

		String displayName = rank.getDisplayName() != null ? rank.getDisplayName() : rank.getName();

		iconLabel.setPreferredSize(new Dimension(18, 18));

		JLabel nameLabel = new JLabel(displayName);
		nameLabel.setFont(FontManager.getRunescapeBoldFont());
		nameLabel.setForeground(UIConstants.ACCENT_GOLD);

		JPanel leftPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		leftPanel.setOpaque(false);
		leftPanel.add(iconLabel);
		leftPanel.add(nameLabel);

		String pointsText = formatPoints(rank.getPointsRequired());
		if (rank.getMaintenancePerMonth() > 0) {
			pointsText += " (" + rank.getMaintenancePerMonth() + "/mo)";
		}

		JLabel pointsLabel = new JLabel(pointsText);
		pointsLabel.setFont(FontManager.getRunescapeBoldFont());
		pointsLabel.setForeground(UIConstants.POINTS_COLOR);

		add(leftPanel, BorderLayout.WEST);
		add(pointsLabel, BorderLayout.EAST);

		if (rank.getAdditionalRequirements() != null && !rank.getAdditionalRequirements().isEmpty()) {
			StringBuilder tooltip = new StringBuilder();
			for (PointsResponse.Rank.AdditionalRequirement req : rank.getAdditionalRequirements()) {
				if (tooltip.length() > 0) tooltip.append(", ");
				tooltip.append(req.getDescription());
			}
			setToolTipText(tooltip.toString());
		}

		if (iconResolver != null && rank.getName() != null) {
			iconResolver.apply(rank.getName(), iconLabel, 18);
		}
	}

	private String formatPoints(int points) {
		if (points >= 1000) {
			return String.format("%.1fk", points / 1000.0);
		}
		return String.valueOf(points);
	}

	@Override
	protected void paintComponent(Graphics g) {
		Graphics2D g2d = (Graphics2D) g.create();
		g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2d.setColor(getBackground());
		g2d.fillRoundRect(0, 0, getWidth(), getHeight(), 6, 6);
		g2d.dispose();
	}
}

package com.revalclan.ui.components;

import com.revalclan.ui.constants.UIConstants;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

public class RefreshButton extends JButton {
	private boolean loading = false;

	public RefreshButton(Runnable onRefresh) {
		super("Refresh");
		setFont(FontManager.getRunescapeSmallFont());
		setForeground(UIConstants.TEXT_PRIMARY);
		setBorder(new EmptyBorder(4, 8, 4, 8));
		setContentAreaFilled(false);
		setBorderPainted(false);
		setFocusPainted(false);
		setVerticalAlignment(SwingConstants.CENTER);
		setVerticalTextPosition(SwingConstants.CENTER);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		addActionListener(e -> {
			if (!loading) onRefresh.run();
		});
	}

	public void setLoading(boolean loading) {
		this.loading = loading;
		setText(loading ? "Loading..." : "Refresh");
		setEnabled(!loading);
	}

	@Override
	protected void paintComponent(Graphics g) {
		if (getModel().isRollover() && !loading) {
			Graphics2D g2d = (Graphics2D) g.create();
			g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2d.setColor(UIConstants.CARD_HOVER);
			g2d.fillRoundRect(0, 0, getWidth(), getHeight(), 6, 6);
			g2d.dispose();
		}
		super.paintComponent(g);
	}
}

