import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Leagues Bingo inside the side panel: pick a team, pick one of its region
 * boards, then browse the tiles. Mirrors the homepage showcase, fed by the
 * same public payload, sized for the 225px RuneLite panel.
 */
@Singleton
public class LeaguesBingoPanel extends JPanel {
	private enum View { TEAMS, BOARDS, BOARD }

	private static final long FRESH_MS = 45_000;
	private static final int TEXT_WIDTH = 158;

	private final RevalApiService api;
	private final Client client;
	private final SpriteManager spriteManager;
	private final TileIcons tileIcons;
	private Runnable onClose = () -> {};

	private final BackButton backButton;
	private final JLabel titleLabel;
	private final RefreshButton refreshButton;
	private final JPanel body;
	private final JScrollPane scroll;

	private EventsResponse.EventSummary event;
	private Payload payload;
	/** What the backend says this account may do here; null until answered. */
	private LeaguesBingoMeResponse.Viewer me;
	private long loadedAt;
	private boolean loading;
	private boolean picking;
	private String loadError;

	private View view = View.TEAMS;
	private String teamId;
	private String region;
	private String tileId;
	private BoardGridView grid;
	private JPanel tileDetailHolder;

	@Inject
	public LeaguesBingoPanel(RevalApiService api, Client client, ItemManager itemManager, SpriteManager spriteManager) {
		this.api = api;
		this.client = client;
		this.spriteManager = spriteManager;
		this.tileIcons = new TileIcons(itemManager);

		setLayout(new BorderLayout());
		setBackground(UIConstants.BACKGROUND);

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(UIConstants.CARD_BG);
		header.setBorder(new EmptyBorder(6, 6, 6, 6));
		backButton = new BackButton("< Back", this::back);
		titleLabel = new JLabel("");
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setForeground(UIConstants.ACCENT_GOLD);
		titleLabel.setHorizontalAlignment(JLabel.CENTER);
		refreshButton = new RefreshButton(this::refresh);
		header.add(backButton, BorderLayout.WEST);
		header.add(titleLabel, BorderLayout.CENTER);
		header.add(refreshButton, BorderLayout.EAST);
		add(header, BorderLayout.NORTH);

		body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(UIConstants.BACKGROUND);
		body.setBorder(new EmptyBorder(10, 8, 12, 8));
		scroll = ScrollWrap.of(body);
		add(scroll, BorderLayout.CENTER);
	}

	/** Called when the user backs out of the team list. */
	public void setOnClose(Runnable onClose) {
		this.onClose = onClose;
	}

	// ==================== Navigation ====================

	/** Show the event, starting at the team list. Re-uses a recent payload. */
	public void open(EventsResponse.EventSummary event) {
		boolean sameEvent = this.event != null && this.event.getId().equals(event.getId());
		if (!sameEvent) reset();
		this.event = event;
		view = View.TEAMS;
		loadError = null;
		if (payload == null || System.currentTimeMillis() - loadedAt > FRESH_MS) {
			load();
		}
		render(true);
	}

	public void refresh() {
		if (event != null && !loading) load();
	}

	/** Forget everything, including who may pick: the next account starts clean. */
	public void reset() {
		event = null;
		payload = null;
		me = null;
		loadedAt = 0;
		loadError = null;
		teamId = null;
		region = null;
		tileId = null;
		view = View.TEAMS;
	}

	private void back() {
		tileId = null;
		switch (view) {
			case BOARD:
				view = View.BOARDS;
				break;
			case BOARDS:
				view = View.TEAMS;
				break;
			default:
				onClose.run();
				return;
		}
		render(true);
	}

	private void showBoards(Team team) {
		teamId = team.getId();
		region = null;
		tileId = null;
		view = View.BOARDS;
		render(true);
	}

	private void showBoard(String regionId) {
		region = regionId;
		tileId = null;
		view = View.BOARD;
		render(true);
	}

	// ==================== Loading ====================

	private void load() {
		loading = true;
		loadError = null;
		refreshButton.setLoading(true);
		loadViewer();
		api.fetchLeaguesBingoEvent(event.getId(),
			response -> SwingUtilities.invokeLater(() -> {
				loading = false;
				refreshButton.setLoading(false);
				payload = response.getData();
				loadedAt = System.currentTimeMillis();
				render(false);
			}),
			error -> SwingUtilities.invokeLater(() -> {
				loading = false;
				refreshButton.setLoading(false);
				loadError = error.getMessage();
				render(false);
			}));
	}

	/** Ask the backend what this account may do; a failure just hides the pick buttons. */
	private void loadViewer() {
		long accountHash = client != null ? client.getAccountHash() : -1;
		if (accountHash == -1) return;
		api.fetchLeaguesBingoMe(event.getId(), accountHash,
			response -> SwingUtilities.invokeLater(() -> {
				me = response.getData();
				if (view != View.TEAMS) render(false);
			}),
			error -> SwingUtilities.invokeLater(() -> me = null));
	}

	// ==================== Rendering ====================

	private void render(boolean scrollToTop) {
		body.removeAll();
		grid = null;
		tileDetailHolder = null;

		Team team = payload != null ? payload.teamById(teamId) : null;
		if (view != View.TEAMS && team == null) view = View.TEAMS;

		switch (view) {
			case BOARDS:
				setHeader("< Teams", team.getName(), teamColor(team));
				break;
			case BOARD:
				setHeader("< Boards", LeaguesRegions.byId(region).getDisplayName(), LeaguesRegions.byId(region).getAccent());
				break;
			default:
				setHeader("< Events", event != null ? event.getName() : "", UIConstants.ACCENT_GOLD);
		}

		if (payload == null) {
			body.add(statusView());
		} else if (view == View.BOARDS) {
			buildBoardsView(team);
		} else if (view == View.BOARD) {
			buildBoardView(team);
		} else {
			buildTeamsView();
		}

		body.revalidate();
		body.repaint();
		if (scrollToTop) {
			SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(0));
		}
	}

	private void setHeader(String backText, String title, Color titleColor) {
		backButton.setText(backText);
		titleLabel.setText(title);
		titleLabel.setForeground(titleColor);
	}

	private JComponent statusView() {
		if (loading) return Labels.centered(Labels.small("Loading boards...", UIConstants.TEXT_MUTED));
		if (loadError != null) {
			return Labels.centered(Labels.wrapped("Failed to load: " + loadError, FontManager.getRunescapeSmallFont(), UIConstants.ERROR_COLOR, TEXT_WIDTH + 20));
		}
		return Labels.centered(Labels.small("No board data", UIConstants.TEXT_MUTED));
	}

	// ---------- Teams ----------

	private void buildTeamsView() {
		body.add(TeamCards.eventSummary(payload));
		body.add(Box.createVerticalStrut(10));
		body.add(Labels.sectionTitle("Standings"));
		body.add(Box.createVerticalStrut(6));

		List<Team> teams = new ArrayList<>(payload.getTeams());
		teams.sort(Comparator.comparingInt(Team::getScore).reversed()
			.thenComparing(Comparator.comparingInt(Team::getUniqueCompletedTiles).reversed()));
		if (teams.isEmpty()) {
			body.add(Labels.centered(Labels.small("No teams yet", UIConstants.TEXT_MUTED)));
			return;
		}

		String me = localPlayerName();
		int rank = 1;
		for (Team team : teams) {
			body.add(TeamCards.row(team, rank++, team.hasMember(me), () -> showBoards(team)));
			body.add(Box.createVerticalStrut(6));
		}
		body.add(Box.createVerticalStrut(4));
		body.add(Labels.centered(Labels.small("Pick a team to see its boards", UIConstants.TEXT_MUTED)));
	}

	// ---------- Boards ----------

	private void buildBoardsView(Team team) {
		body.add(TeamCards.chip(team, payload, true));
		body.add(Box.createVerticalStrut(10));
		body.add(Labels.sectionTitle("Boards"));
		body.add(Box.createVerticalStrut(6));

		// Unlocked boards in the order the team unlocked them, locked ones after.
		List<Board> boards = new ArrayList<>(payload.getBoards());
		boards.sort(Comparator.comparing((Board b) -> team.hasUnlocked(b.getRegion()) ? 0 : 1)
			.thenComparing(b -> unlockedAt(team, b.getRegion()), Comparator.nullsLast(Comparator.naturalOrder()))
			.thenComparingInt(b -> LeaguesRegions.order(b.getRegion())));

		for (Board board : boards) {
			AccentCard card = boardSummary(team, board, UIConstants.TEXT_PRIMARY, true);
			Clickable.onPress(card, () -> showBoard(board.getRegion()), card::setHovered);
			body.add(card);
			body.add(Box.createVerticalStrut(6));
		}
	}

	/** ISO-8601 timestamps sort correctly as strings. */
	private static String unlockedAt(Team team, String region) {
		UnlockedRegion u = team.unlockFor(region);
		return u != null ? u.getUnlockedAt() : null;
	}

	/** Summary block shared by the board list and the board header; bottom slot = unlock button or progress bar. */
	private AccentCard boardSummary(Team team, Board board, Color nameColor, boolean hoverable) {
		LeaguesRegions.Region meta = LeaguesRegions.byId(board.getRegion());
		BoardStats stats = BoardStats.of(team, board);
		JComponent bottom = canUnlock(team, board, stats) ? unlockButton(team, board) : new ProgressBar(stats.percent(), meta.getAccent());
		return BoardSummaryCard.build(meta, stats, board, spriteManager, nameColor, hoverable, bottom);
	}

	// ---------- Board ----------

	private void buildBoardView(Team team) {
		Board board = payload.boardFor(region);
		if (board == null) {
			body.add(Labels.centered(Labels.small("Board not found", UIConstants.TEXT_MUTED)));
			return;
		}
		LeaguesRegions.Region meta = LeaguesRegions.byId(region);
		BoardStats stats = BoardStats.of(team, board);

		body.add(TeamCards.chip(team, payload, false));
		body.add(Box.createVerticalStrut(8));
		body.add(boardSummary(team, board, meta.getAccent(), false));
		body.add(Box.createVerticalStrut(10));

		grid = new BoardGridView(payload, team, board, meta, stats, tileIcons, tileId, tile -> {
			tileId = tile.getBoardTileId().equals(tileId) ? null : tile.getBoardTileId();
			grid.setSelected(tileId);
			renderTileDetail(team, board, stats);
		});
		body.add(grid);
		body.add(Box.createVerticalStrut(10));

		tileDetailHolder = new JPanel();
		tileDetailHolder.setLayout(new BoxLayout(tileDetailHolder, BoxLayout.Y_AXIS));
		tileDetailHolder.setOpaque(false);
		tileDetailHolder.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(tileDetailHolder);
		renderTileDetail(team, board, stats);
	}

	private void renderTileDetail(Team team, Board board, BoardStats stats) {
		tileDetailHolder.removeAll();
		Tile tile = null;
		for (Tile t : board.getTiles()) {
			if (t.getBoardTileId().equals(tileId)) tile = t;
		}
		if (tile == null) {
			String hint = payload.isTilesHidden() ? "Tiles are hidden until the reveal" : "Click a tile to see its task and progress";
			tileDetailHolder.add(Labels.centered(Labels.wrapped(hint, FontManager.getRunescapeSmallFont(), UIConstants.TEXT_MUTED, TEXT_WIDTH + 10)));
		} else {
			tileDetailHolder.add(TileDetailView.build(team, tile, stats.isLocked()));
		}
		tileDetailHolder.revalidate();
		tileDetailHolder.repaint();
	}

	// ==================== Region picks ====================

	/**
	 * A locked, non-default board this viewer may unlock for the team right
	 * now. Board contents and double picks are the backend's rules.
	 */
	private boolean canUnlock(Team team, Board board, BoardStats stats) {
		return me != null && me.canPickFor(team.getId())
			&& stats.isLocked()
			&& !payload.isDefaultRegion(board.getRegion())
			&& team.availableTokens() > 0;
	}

	private JComponent unlockButton(Team team, Board board) {
		JButton button = new AccentButton("Unlock board", UIConstants.ACCENT_GOLD);
		button.setForeground(UIConstants.BACKGROUND);
		button.setPreferredSize(new Dimension(100, 22));
		button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		button.setToolTipText("Spend one pick token to unlock this board");
		button.setEnabled(!picking);
		button.addActionListener(e -> confirmUnlock(team, board));
		return button;
	}

	private void confirmUnlock(Team team, Board board) {
		if (picking || me == null) return;
		LeaguesRegions.Region meta = LeaguesRegions.byId(board.getRegion());
		int tokens = team.availableTokens();
		String summary = "<html><body style='width:230px'>"
			+ "<b>Unlock " + Labels.escapeHtml(meta.getDisplayName()) + " for " + Labels.escapeHtml(team.getName()) + "?</b><br><br>"
			+ board.getRows() + "x" + board.getColumns() + " board, " + board.getTiles().size() + " tiles, "
			+ board.getTotalPoints() + " points.<br>"
			+ "This spends 1 of " + tokens + " pick token" + (tokens != 1 ? "s" : "") + " and cannot be undone."
			+ (me.isSuperadmin() && !me.isOwnTeam(team.getId()) ? "<br><br><i>You are unlocking as a superadmin.</i>" : "")
			+ "</body></html>";
		int choice = JOptionPane.showConfirmDialog(this, summary, "Unlock region", JOptionPane.OK_CANCEL_OPTION, JOptionPane.QUESTION_MESSAGE);
		if (choice != JOptionPane.OK_OPTION) return;

		long accountHash = client != null ? client.getAccountHash() : -1;
		if (accountHash == -1) return;
		picking = true;
		render(false);
		// Pickers act for their own team; only a superadmin names another team.
		String targetTeam = me.isOwnTeam(team.getId()) ? null : team.getId();
		api.pickLeaguesBingoRegion(event.getId(), accountHash, board.getRegion(), targetTeam,
			response -> SwingUtilities.invokeLater(() -> {
				picking = false;
				if (response.getData() != null && response.getData().getMe() != null) me = response.getData().getMe();
				load();
				JOptionPane.showMessageDialog(this, meta.getDisplayName() + " unlocked for " + team.getName() + ".",
					"Region unlocked", JOptionPane.INFORMATION_MESSAGE);
			}),
			error -> SwingUtilities.invokeLater(() -> {
				picking = false;
				render(false);
				JOptionPane.showMessageDialog(this, "Could not unlock: " + error.getMessage(), "Unlock failed", JOptionPane.WARNING_MESSAGE);
			}));
	}

	// ==================== Helpers ====================

	private String localPlayerName() {
		try {
			return client != null && client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
		} catch (RuntimeException e) {
			return null;
		}
	}

	static Color teamColor(Team team) {
		return TeamColor.onDarkPanel(TeamColor.parse(team.getColor()));
	}
}

package com.revalclan.ui.leaguesbingo;

import lombok.Value;
import net.runelite.api.gameval.SpriteID;

import java.awt.Color;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * The 13 fixed Leagues Bingo regions, mirroring the app's regions.ts so the
 * side panel uses the same names, order and accent colors as the homepage.
 */
public final class LeaguesRegions {
	@Value
	public static class Region {
		String id;
		String displayName;
		Color accent;
		/** Area banner from the game cache (Leagues map shield), or -1. */
		int bannerSprite;
		/** Same banner with the game's highlight border, for a finished board; or -1. */
		int bannerHighlightSprite;
	}

	/*
	 * Banner sprites are the Leagues VI area shields (League6MapShields02: a
	 * plain 20x30 set followed by a highlighted 22x32 set in the same order).
	 * The order was checked against the wiki's area badges, slot by slot:
	 * 0 Misthalin, 1 Karamja, 2 Asgarnia, 3 Desert, 4 Morytania, 5 Wilderness,
	 * 6 Kandarin, 7 Fremennik, 8 Tirannwn, 9 Kourend, 10 Varlamore. Slot 11
	 * (crossed swords) has no area of its own and stands in for Global;
	 * Sailing uses the skill icon.
	 */
	public static final List<Region> ALL = Arrays.asList(
		new Region("varlamore", "Varlamore", new Color(0xe8c258), SpriteID.League6MapShields02._10, SpriteID.League6MapShields02._22),
		new Region("karamja", "Karamja", new Color(0x57a64a), SpriteID.League6MapShields02._1, SpriteID.League6MapShields02._13),
		new Region("asgarnia", "Asgarnia", new Color(0x4f7ee3), SpriteID.League6MapShields02._2, SpriteID.League6MapShields02._14),
		new Region("desert", "Desert", new Color(0xd1913f), SpriteID.League6MapShields02._3, SpriteID.League6MapShields02._15),
		new Region("fremennik", "Fremennik", new Color(0x9ec7dd), SpriteID.League6MapShields02._7, SpriteID.League6MapShields02._19),
		new Region("kandarin", "Kandarin", new Color(0xd9534f), SpriteID.League6MapShields02._6, SpriteID.League6MapShields02._18),
		new Region("morytania", "Morytania", new Color(0x9b59b6), SpriteID.League6MapShields02._4, SpriteID.League6MapShields02._16),
		new Region("tirannwn", "Tirannwn", new Color(0x45c48f), SpriteID.League6MapShields02._8, SpriteID.League6MapShields02._20),
		new Region("wilderness", "Wilderness", new Color(0x8b8b8b), SpriteID.League6MapShields02._5, SpriteID.League6MapShields02._17),
		new Region("kourend", "Kourend", new Color(0x3aa6a6), SpriteID.League6MapShields02._9, SpriteID.League6MapShields02._21),
		new Region("misthalin", "Misthalin", new Color(0x6faedb), SpriteID.League6MapShields02._0, SpriteID.League6MapShields02._12),
		new Region("global", "Global", new Color(0xe3b341), SpriteID.League6MapShields02._11, SpriteID.League6MapShields02._23),
		new Region("sailing", "Sailing", new Color(0x3b9ec9), SpriteID.Staticons2.SAILING, SpriteID.Staticons2.SAILING)
	);

	private static final Map<String, Region> BY_ID = new LinkedHashMap<>();
	/** Ids the backend may send that we do not know; one placeholder each, built once. */
	private static final Map<String, Region> UNKNOWN = new ConcurrentHashMap<>();
	private static final Color UNKNOWN_ACCENT = new Color(0x8b8b8b);

	static {
		for (Region r : ALL) BY_ID.put(r.getId(), r);
	}

	public static Region byId(String id) {
		String key = id == null ? "" : id.toLowerCase();
		Region known = BY_ID.get(key);
		if (known != null) return known;
		return UNKNOWN.computeIfAbsent(key, k ->
			new Region(k, k.isEmpty() ? "Unknown" : Character.toUpperCase(k.charAt(0)) + k.substring(1), UNKNOWN_ACCENT, -1, -1));
	}

	/** Position of a region in the canonical order; unknown ids sort last. */
	public static int order(String id) {
		int i = 0;
		for (Region r : ALL) {
			if (r.getId().equalsIgnoreCase(id)) return i;
			i++;
		}
		return ALL.size();
	}

	private LeaguesRegions() {
	}
}

package com.revalclan.ui.leaguesbingo;

import com.google.gson.JsonObject;
import com.revalclan.util.Json;
import com.revalclan.util.NumberFmt;

import java.util.ArrayList;
import java.util.List;

/**
 * One-line human descriptions of tile requirements, ported from the
 * homepage's tile modal so both surfaces read the same way.
 */
public final class RequirementText {
	private RequirementText() {
	}

	public static String describe(JsonObject r) {
		// Admins can attach their own wording; it beats anything we derive.
		String custom = Json.str(r, "description", "").trim();
		return custom.isEmpty() ? derive(r) : custom;
	}

	/** Everything a requirement lets the team choose from: items, then pets. */
	public static List<String> optionNames(JsonObject r) {
		List<String> names = itemNames(r);
		names.addAll(petNames(r));
		return names;
	}

	/** Item names for ITEM_DROP style requirements, in order. */
	public static List<String> itemNames(JsonObject r) {
		return Json.strings(Json.array(r, "items"), "itemName");
	}

	private static List<String> petNames(JsonObject r) {
		return Json.strings(Json.array(r, "pets"), "petName");
	}

	private static String derive(JsonObject r) {
		String type = Json.str(r, "type", "");
		switch (type) {
			case "ITEM_DROP": {
				List<String> names = itemNames(r);
				int total = Json.num(r, "totalAmount", 0);
				if (total > 0) {
					return Json.bool(r, "allowDuplicates")
						? "Any " + total + " of " + names.size() + " items"
						: total + " unique of " + names.size() + " items";
				}
				if (names.size() <= 1) return "Obtain " + (names.isEmpty() ? "item" : names.get(0));
				return "Collect all " + names.size() + " items";
			}
			case "GP_EARNING": return "Earn " + NumberFmt.compact(Json.num(r, "targetValue", Json.num(r, "value", 0))) + " GP from the list";
			case "VALUE_DROP": return "A single drop worth " + NumberFmt.compact(Json.num(r, "minValue", Json.num(r, "value", 0))) + "+";
			case "EXPERIENCE":
			case "SKILL_XP": return NumberFmt.group(Json.num(r, "experience", 0)) + " " + Json.str(r, "skill", "") + " XP";
			case "SPEEDRUN": return Json.str(r, "location", "Speedrun") + " under " + mmss(Json.num(r, "goalSeconds", Json.num(r, "time", 0)));
			case "KILL_COUNT": return numOr(r, "count") + "x " + Json.str(r, "target", Json.str(r, "npcName", "?")) + " KC";
			case "DETAILED_KILL": return Json.num(r, "count", 1) + "x " + Json.str(r, "target", "?");
			case "PET": {
				List<String> pets = petNames(r);
				if (pets.size() > 1) return Json.num(r, "anyCount", Json.num(r, "totalAmount", 1)) + " unique of " + pets.size() + " pets";
				if (pets.size() == 1) return "Pet: " + pets.get(0);
				return "Pet: " + Json.str(r, "petName", "?");
			}
			case "ALPHABET_KILL": return "Kill a boss for each letter";
			case "PUZZLE": return Json.str(r, "displayName", "Puzzle");
			case "COMBAT_ACHIEVEMENT": return "CA: " + Json.str(r, "achievementName", Json.str(r, "tier", "?"));
			case "COMBAT_ACHIEVEMENT_TIER": return "All " + Json.str(r, "tier", "?") + "-tier combat achievements";
			case "QUEST": return "Quest: " + Json.str(r, "questName", "?");
			case "ACHIEVEMENT_DIARY": return (Json.str(r, "diaryName", "") + " diary (" + Json.str(r, "tier", "?") + ")").trim();
			case "COLLECTION_LOG": return numOr(r, "count") + " collection log slots";
			case "COLLECTION_LOG_TIER": return "Collection log tier: " + Json.str(r, "tier", "?");
			case "KILL_STREAK": return numOr(r, "count") + " " + Json.str(r, "target", "?") + " kills in a row, no deaths";
			case "SKILL_LEVEL": return (Json.str(r, "skill", "") + " level " + numOr(r, "level")).trim();
			case "TOTAL_LEVEL": return "Total level " + numOr(r, "level");
			case "TOTAL_XP": return NumberFmt.group(Json.num(r, "experience", 0)) + " total XP";
			case "PERSONAL_BEST": return "New PB: " + Json.str(r, "location", "?");
			case "CLUE_COMPLETION": return numOr(r, "count") + "x " + Json.str(r, "tier", "?") + " clue";
			case "CLUE_ITEM": {
				List<String> names = itemNames(r);
				return "Clue item: " + (names.isEmpty() ? "?" : String.join(", ", names));
			}
			case "BA_GAMBLES": return numOr(r, "count") + " BA high gambles";
			case "MINIGAME_SCORE": return Json.str(r, "minigame", "?") + ": " + Json.num(r, "score", 0) + " score";
			case "CHAT_MESSAGE": {
				String message = Json.str(r, "message", Json.str(r, "pattern", ""));
				int count = Json.num(r, "count", 1);
				if (message.isEmpty()) return count > 1 ? count + "x game message" : "Game message";
				return (count > 1 ? count + "x " : "") + "\"" + message + "\"";
			}
			case "EMOTE": return "Emote: " + Json.str(r, "emoteName", "?");
			case "MUSIC_PLAYED": return "Play track: " + Json.str(r, "trackName", "?");
			case "MANUAL": {
				String v = Json.str(r, "verificationDescription", "");
				return v.isEmpty() ? "Manually verified by an admin" : v;
			}
			case "PET_COUNT": return numOr(r, "count") + " unique pets";
			case "ITEM_DROP_REQUIREMENT": return Json.num(r, "requiredCount", 2) + "+ items in a single drop";
			case "LEAGUES_AREA": return "Unlock area: " + Json.str(r, "areaName", "?");
			case "LEAGUES_RELIC": {
				String name = Json.str(r, "relicName", "");
				return "Relic: " + (name.isEmpty() ? "tier " + numOr(r, "relicTier") : name);
			}
			case "LEAGUES_TASK_COUNT": return numOr(r, "minTaskCount") + " league tasks";
			case "LEAGUES_POINTS": return numOr(r, "minPoints") + " league points";
			case "LEAGUES_MASTERY": return numOr(r, "minNodes") + " pact nodes";
			case "COMPOUND": return "All sub-requirements";
			case "CHOICE": return Json.num(r, "requiredCount", 1) + " of the options";
			case "SCHEDULED": return "Scheduled (time window)";
			default: return type.isEmpty() ? "Requirement" : type;
		}
	}

	private static String numOr(JsonObject o, String key) {
		Double d = Json.number(o, key);
		return d == null ? "?" : NumberFmt.group(d.longValue());
	}

	private static String mmss(int seconds) {
		return String.format("%d:%02d", seconds / 60, seconds % 60);
	}
}

package com.revalclan.ui.leaguesbingo;

