package com.revalclan.util;

import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;

public class DateTimeUtil {
	private static final DateTimeFormatter SHORT = DateTimeFormatter.ofPattern("MMM d HH:mm");

	/** "Sep 4 21:59" in the user's zone; the raw string when it does not parse. */
	public static String formatShort(String iso) {
		try {
			return parseToLocal(iso).format(SHORT);
		} catch (RuntimeException e) {
			return iso;
		}
	}


	/**
	 * Parses an ISO 8601 timestamp (with or without zone) as UTC,
	 * then converts to the user's local timezone.
	 */
	public static ZonedDateTime parseToLocal(String iso) {
		try {
			return ZonedDateTime.parse(iso)
				.withZoneSameInstant(ZoneId.systemDefault());
		} catch (DateTimeParseException e) {
			return LocalDateTime.parse(iso)
				.atZone(ZoneOffset.UTC)
				.withZoneSameInstant(ZoneId.systemDefault());
		}
	}

	/**
	 * Parses an ISO 8601 timestamp (with or without zone) to a UTC Instant.
	 */
	public static Instant parseToInstant(String iso) {
		try {
			return Instant.parse(iso);
		} catch (DateTimeParseException e) {
			return LocalDateTime.parse(iso).toInstant(ZoneOffset.UTC);
		}
	}
}

package com.revalclan.util;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.*;
import java.util.List;

/**
 * Manages dynamic event filters fetched from the backend API
 */
@Slf4j
@Singleton
public class EventFilterManager{
	private static final String FILTERS_URL = "https://api.revalosrs.ee/event-filters";

	@Inject private OkHttpClient httpClient;

	@Inject private Gson gson;

	@Getter private volatile EventFilters filters;
	private String appliedVersion;
	private boolean fetchInProgress;
	private int generation;
	private int ticksRemaining;
	private static final int DAILY_TICKS = 144_000;
	private static final int RETRY_TICKS = 100; // One minute after a failed fetch.

	/** Runs after every successful fetch, once the new filters are in place. */
	@Setter private Runnable onFiltersApplied;

	/**
	 * Holds all filter configurations
	 */
	@Getter
	public static class EventFilters {
		// Loot filter settings
		@Getter private long lootMinValue = 1_000_000; // 1M default
		@Getter private Set<Integer> lootWhitelist = new HashSet<>();
		@Getter private Set<Integer> lootBlacklist = new HashSet<>(Arrays.asList(526, 995)); // Bones, Coins

		// Detailed kill filter settings
		@Getter private Set<Integer> detailedKillNpcIdWhitelist = new HashSet<>();
		@Getter private Set<Integer> detailedKillNpcIdBlacklist = new HashSet<>();
		/** NPC names (lowercase) needed by active server-side requirements; matched by containment */
		@Getter private Set<String> detailedKillNpcNameWhitelist = new HashSet<>();

		// Chat filter settings
		@Getter private List<String> chatPatterns = new ArrayList<>(); // Empty by default = no patterns, all messages pass

		/**
		 * Item names (lowercase) whose silent consumption is reported. Derived by
		 * the backend from live tile requirements; nothing is built into the
		 * plugin, and empty means watch nothing.
		 */
		@Getter private Set<String> inventoryWatchItems = new HashSet<>();
		/** Watched item names as the backend spelled them, keyed lowercased. */
		@Getter private Map<String, String> inventoryWatchItemNames = new HashMap<>();

		/** Varbit ids whose value the plugin reports (varbits.watch). Empty by default. */
		@Getter private Set<Integer> varbitWatch = new HashSet<>();

		// Event toggles
		@Getter private boolean lootEnabled = true;
		@Getter private boolean petEnabled = true;
		@Getter private boolean questEnabled = true;
		@Getter private boolean levelEnabled = true;
		@Getter private boolean killCountEnabled = true;
		@Getter private boolean clueEnabled = true;
		@Getter private boolean diaryEnabled = true;
		@Getter private boolean combatAchievementEnabled = true;
		@Getter private boolean collectionEnabled = true;
		@Getter private boolean deathEnabled = true;
		@Getter private boolean detailedKillEnabled = true;
		@Getter private boolean emoteEnabled = true;
		@Getter private boolean chatEnabled = true;
		@Getter private boolean musicEnabled = true;
		@Getter private boolean leaguesEnabled = false;
	}

	public EventFilterManager() {
		// Initialize with defaults
		filters = new EventFilters();
	}

	public synchronized void resetSession() {
		generation++;
		fetchInProgress = false;
		appliedVersion = null;
		ticksRemaining = 0;
	}

	public synchronized void onGameTick() {
		if (!fetchInProgress && --ticksRemaining <= 0) fetchFiltersAsync();
	}

	/** A missing hint falls back to heartbeat-paced fetching during rollout/outages. */
	public synchronized void onServerVersion(String version) {
		if (version == null || !version.equals(appliedVersion)) fetchFiltersAsync();
	}

	public synchronized void fetchFiltersAsync() {
		if (fetchInProgress) return;
		fetchInProgress = true;
		final int requestGeneration = generation;
		Request request = new Request.Builder().url(FILTERS_URL).get()
			.addHeader("User-Agent", PluginVersion.userAgent()).build();
		httpClient.newCall(request).enqueue(new Callback() {
			@Override public void onFailure(Call call, IOException error) {
				synchronized (EventFilterManager.this) {
					if (requestGeneration != generation) return;
					fetchInProgress = false;
					ticksRemaining = RETRY_TICKS;
				}
				log.warn("Failed to fetch filters", error);
			}

			@Override public void onResponse(Call call, Response response) {
				try (Response closeable = response) {
					JsonObject json = response.isSuccessful() && response.body() != null
						? gson.fromJson(response.body().string(), JsonObject.class) : null;
					EventFilters parsed = json == null ? null : parseFilters(json);
					Runnable listener;
					synchronized (EventFilterManager.this) {
						if (requestGeneration != generation) return;
						fetchInProgress = false;
						ticksRemaining = RETRY_TICKS;
						if (parsed == null) return;
						filters = parsed;
						appliedVersion = response.header("X-Reval-Filters-Version");
						ticksRemaining = DAILY_TICKS;
						listener = onFiltersApplied;
					}
					if (listener != null) listener.run();
				} catch (Exception error) {
					onFailure(call, new IOException("Invalid filter response", error));
				}
			}
		});
	}

	/**
	 * Parse the filters JSON response
	 */
	private EventFilters parseFilters(JsonObject json) {
		EventFilters newFilters = new EventFilters();

		try {
			// Parse loot filters
			if (json.has("loot")) {
				JsonObject loot = json.getAsJsonObject("loot");

				if (loot.has("minValue")) {
					newFilters.lootMinValue = loot.get("minValue").getAsLong();
				}

				// Clear defaults and only use API values
				newFilters.lootWhitelist.clear();
				if (loot.has("whitelist") && loot.get("whitelist").isJsonArray()) {
					loot.getAsJsonArray("whitelist").forEach(item -> 
						newFilters.lootWhitelist.add(item.getAsInt())
					);
				}

				newFilters.lootBlacklist.clear();
				if (loot.has("blacklist") && loot.get("blacklist").isJsonArray()) {
					loot.getAsJsonArray("blacklist").forEach(item -> 
						newFilters.lootBlacklist.add(item.getAsInt())
					);
				}
			}

			// Parse detailed kill filters
			if (json.has("detailedKill")) {
				JsonObject detailedKill = json.getAsJsonObject("detailedKill");

				// Clear defaults and only use API values
				newFilters.detailedKillNpcIdWhitelist.clear();
				if (detailedKill.has("npcIdWhitelist") && detailedKill.get("npcIdWhitelist").isJsonArray()) {
					detailedKill.getAsJsonArray("npcIdWhitelist").forEach(id -> 
						newFilters.detailedKillNpcIdWhitelist.add(id.getAsInt())
					);
				}

				newFilters.detailedKillNpcIdBlacklist.clear();
				if (detailedKill.has("npcIdBlacklist") && detailedKill.get("npcIdBlacklist").isJsonArray()) {
					detailedKill.getAsJsonArray("npcIdBlacklist").forEach(id ->
						newFilters.detailedKillNpcIdBlacklist.add(id.getAsInt())
					);
				}

				newFilters.detailedKillNpcNameWhitelist.clear();
				if (detailedKill.has("npcNameWhitelist") && detailedKill.get("npcNameWhitelist").isJsonArray()) {
					detailedKill.getAsJsonArray("npcNameWhitelist").forEach(name ->
						newFilters.detailedKillNpcNameWhitelist.add(name.getAsString().toLowerCase())
					);
				}
			}

			// Parse inventory watches
			if (json.has("inventory")) {
				JsonObject inventory = json.getAsJsonObject("inventory");

				newFilters.inventoryWatchItems.clear();
				newFilters.inventoryWatchItemNames.clear();
				if (inventory.has("watchItems") && inventory.get("watchItems").isJsonArray()) {
					inventory.getAsJsonArray("watchItems").forEach(item -> {
						String name = item.getAsString().trim().toLowerCase();
						if (!name.isEmpty()) {
							newFilters.inventoryWatchItems.add(name);
							newFilters.inventoryWatchItemNames.put(name, item.getAsString().trim());
						}
					});
				}
			}

			if (json.has("varbits")) {
				JsonObject varbits = json.getAsJsonObject("varbits");

				newFilters.varbitWatch.clear();
				if (varbits.has("watch") && varbits.get("watch").isJsonArray()) {
					varbits.getAsJsonArray("watch").forEach(id -> {
						if (id.isJsonPrimitive() && id.getAsJsonPrimitive().isNumber()) {
							newFilters.varbitWatch.add(id.getAsInt());
						}
					});
				}
				log.info("[Reval] watching varbits {}", newFilters.varbitWatch);
			}

			// Parse chat filters
			if (json.has("chat")) {
				JsonObject chat = json.getAsJsonObject("chat");

				newFilters.chatPatterns.clear();
				if (chat.has("patterns") && chat.get("patterns").isJsonArray()) {
					chat.getAsJsonArray("patterns").forEach(pattern -> 
						newFilters.chatPatterns.add(pattern.getAsString())
					);
				}
			}

			// Parse event toggles
			if (json.has("enabled")) {
				JsonObject enabled = json.getAsJsonObject("enabled");

				if (enabled.has("loot")) newFilters.lootEnabled = enabled.get("loot").getAsBoolean();
				if (enabled.has("pet")) newFilters.petEnabled = enabled.get("pet").getAsBoolean();
				if (enabled.has("quest")) newFilters.questEnabled = enabled.get("quest").getAsBoolean();
				if (enabled.has("level")) newFilters.levelEnabled = enabled.get("level").getAsBoolean();
				if (enabled.has("killCount")) newFilters.killCountEnabled = enabled.get("killCount").getAsBoolean();
				if (enabled.has("clue")) newFilters.clueEnabled = enabled.get("clue").getAsBoolean();
				if (enabled.has("diary")) newFilters.diaryEnabled = enabled.get("diary").getAsBoolean();
				if (enabled.has("combatAchievement")) newFilters.combatAchievementEnabled = enabled.get("combatAchievement").getAsBoolean();
				if (enabled.has("collection")) newFilters.collectionEnabled = enabled.get("collection").getAsBoolean();
				if (enabled.has("death")) newFilters.deathEnabled = enabled.get("death").getAsBoolean();
				if (enabled.has("detailedKill")) newFilters.detailedKillEnabled = enabled.get("detailedKill").getAsBoolean();
				if (enabled.has("emote")) newFilters.emoteEnabled = enabled.get("emote").getAsBoolean();
				if (enabled.has("chat")) newFilters.chatEnabled = enabled.get("chat").getAsBoolean();
				if (enabled.has("music")) newFilters.musicEnabled = enabled.get("music").getAsBoolean();
				if (enabled.has("leagues")) newFilters.leaguesEnabled = enabled.get("leagues").getAsBoolean();
			}

			return newFilters;
		} catch (Exception e) {
			log.error("Error parsing filters JSON", e);
			return null;
		}
	}
}

package com.revalclan.util;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

import java.util.ArrayList;
import java.util.List;

/** Null-tolerant accessors for loosely typed Gson objects (requirements, progress metadata). */
public final class Json {
	private Json() {
	}

	public static String str(JsonObject o, String key, String fallback) {
		JsonElement e = o == null ? null : o.get(key);
		if (e == null || e.isJsonNull()) return fallback;
		try {
			return e.getAsString();
		} catch (RuntimeException ex) {
			return fallback;
		}
	}

	public static int num(JsonObject o, String key, int fallback) {
		Double d = number(o, key);
		return d == null ? fallback : (int) Math.round(d);
	}

	public static Double number(JsonObject o, String key) {
		JsonElement e = o == null ? null : o.get(key);
		if (e == null || e.isJsonNull()) return null;
		try {
			return e.getAsDouble();
		} catch (RuntimeException ex) {
			return null;
		}
	}

	public static boolean bool(JsonObject o, String key) {
		JsonElement e = o == null ? null : o.get(key);
		try {
			return e != null && !e.isJsonNull() && e.getAsBoolean();
		} catch (RuntimeException ex) {
			return false;
		}
	}

	/** The array under {@code key}, or null when absent or not an array. */
	public static JsonArray array(JsonObject o, String key) {
		JsonElement e = o == null ? null : o.get(key);
		return e != null && e.isJsonArray() ? e.getAsJsonArray() : null;
	}

	/** String field {@code key} of every object in {@code array}, in order, skipping misses. */
	public static List<String> strings(JsonArray array, String key) {
		List<String> out = new ArrayList<>();
		if (array == null) return out;
		for (JsonElement e : array) {
			if (!e.isJsonObject()) continue;
			String v = str(e.getAsJsonObject(), key, null);
			if (v != null) out.add(v);
		}
		return out;
	}
}

package com.revalclan.util;

import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/** Formats integers with space grouping ("12 345") independent of the default locale. */
public final class NumberFmt {
	private NumberFmt() {
	}

	/** "1.5M", "12K", "900" — for GP amounts where the exact figure does not matter. */
	public static String compact(long value) {
		if (value >= 1_000_000_000L) return trimZero(value / 1_000_000_000d) + "B";
		if (value >= 1_000_000L) return trimZero(value / 1_000_000d) + "M";
		if (value >= 1_000L) return trimZero(value / 1_000d) + "K";
		return String.valueOf(value);
	}

	private static String trimZero(double d) {
		String s = String.format(Locale.ROOT, "%.1f", d);
		return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
	}

	public static String group(long value) {
		DecimalFormatSymbols symbols = DecimalFormatSymbols.getInstance(Locale.ROOT);
		symbols.setGroupingSeparator(' ');
		return new DecimalFormat("#,##0", symbols).format(value);
	}
}

package com.revalclan.util;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;
import lombok.extern.slf4j.Slf4j;

/**
 * The plugin's own version, read once from the {@code runelite-plugin.properties}
 * that Gradle copies into the jar. Every HTTP call to the Reval backend identifies
 * itself with {@link #userAgent()} so the server can tell which builds are running.
 */
@Slf4j
public final class PluginVersion {
	private static final String USER_AGENT_PREFIX = "RuneLite-RevalClan-Plugin/";
	private static final String RESOURCE = "/com/revalclan/runelite-plugin.properties";
	private static final String VERSION = load();

	private PluginVersion() {
	}

	public static String userAgent() {
		return USER_AGENT_PREFIX + VERSION;
	}

	private static String load() {
		try (InputStream in = PluginVersion.class.getResourceAsStream(RESOURCE)) {
			if (in != null) {
				Properties props = new Properties();
				props.load(in);
				String version = props.getProperty("version", "").trim();
				if (!version.isEmpty()) {
					return version;
				}
			}
		} catch (IOException e) {
			log.debug("Could not read plugin version", e);
		}
		return "unknown";
	}
}

package com.revalclan.util;

import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * The party behind a raid's loot and completion count (CoX, ToB, ToA), with
 * each member marked as a Reval member or a guest.
 *
 * The party is read live while the player is inside the raid. It is also saved
 * when the final boss dies: a ToB or ToA reward can be claimed later from the
 * chest outside the raid, where the party interface can already be empty.
 * Call on the client thread.
 */
@Singleton
public class RaidPartyTracker {
	static final String CHAMBERS_OF_XERIC = "Chambers of Xeric";
	static final String THEATRE_OF_BLOOD = "Theatre of Blood";
	static final String TOMBS_OF_AMASCUT = "Tombs of Amascut";

	/** First VarClientStr holding a ToB party member name (5 consecutive slots). */
	private static final int TOB_MEMBER_NAME_VARC = 330;
	private static final int TOB_PARTY_MAX_SIZE = 5;

	/** First VarClientStr holding a ToA party member name (8 consecutive slots). */
	private static final int TOA_MEMBER_NAME_VARC = 1099;
	private static final int TOA_PARTY_MAX_SIZE = 8;

	/** A saved party applies to rewards claimed up to this long after the final boss died. */
	static final long SAVED_PARTY_TTL_MS = 10 * 60_000L;

	/** Where a party was read. */
	public enum Origin { LIVE, FINAL_BOSS }

	@Inject private Client client;

	private Party savedParty;
	private long savedAtMs;

	/** Save the party when a raid's final boss dies. Not gated on membership: it only records. */
	public void onActorDeath(ActorDeath event) {
		Actor actor = event.getActor();
		if (!(actor instanceof NPC)) return;
		String raid = raidForFinalBoss(actor.getName());
		if (raid == null) return;

		Party party = readParty(raid, Origin.FINAL_BOSS);
		if (party != null) {
			savedParty = party;
			savedAtMs = System.currentTimeMillis();
		}
	}

	/**
	 * The party for a raid loot or completion source, possibly with a mode suffix
	 * ("Theatre of Blood: Hard Mode"). Null when the source is not a raid or no
	 * party is known.
	 */
	public Party partyFor(String source) {
		String raid = raidOf(source);
		if (raid == null) return null;

		WorldView world = client.getTopLevelWorldView();
		boolean insideRaid = world != null && world.isInstance();
		return choose(raid, readParty(raid, Origin.LIVE), insideRaid, savedParty,
			System.currentTimeMillis() - savedAtMs);
	}

	/** Forget the saved party (logout, plugin stop). */
	public void reset() {
		savedParty = null;
		savedAtMs = 0;
	}

	/**
	 * Inside the raid the live party is the truth. Outside it, a party saved at
	 * this raid's final boss within the TTL wins over whatever the interface
	 * still holds.
	 */
	static Party choose(String raid, Party live, boolean insideRaid, Party saved, long savedAgeMs) {
		if (insideRaid && live != null) return live;
		boolean savedApplies = saved != null && saved.raid.equals(raid)
			&& savedAgeMs >= 0 && savedAgeMs <= SAVED_PARTY_TTL_MS;
		return savedApplies ? saved : live;
	}

	/** The raid a loot or completion source belongs to, or null. */
	static String raidOf(String source) {
		if (source == null) return null;
		if (source.startsWith(CHAMBERS_OF_XERIC)) return CHAMBERS_OF_XERIC;
		if (source.startsWith(THEATRE_OF_BLOOD)) return THEATRE_OF_BLOOD;
		if (source.startsWith(TOMBS_OF_AMASCUT)) return TOMBS_OF_AMASCUT;
		return null;
	}

	/** The raid whose last boss this NPC is, or null. */
	static String raidForFinalBoss(String npcName) {
		switch (sanitize(npcName).replace('’', '\'')) {
			case "Great Olm":
				return CHAMBERS_OF_XERIC;
			case "Verzik Vitur":
				return THEATRE_OF_BLOOD;
			case "Tumeken's Warden":
			case "Elidinis' Warden":
				return TOMBS_OF_AMASCUT;
			default:
				return null;
		}
	}

	private Party readParty(String raid, Origin origin) {
		List<String> names;
		if (CHAMBERS_OF_XERIC.equals(raid)) {
			names = chambersNames();
		} else if (THEATRE_OF_BLOOD.equals(raid)) {
			names = varcNames(TOB_MEMBER_NAME_VARC, TOB_PARTY_MAX_SIZE);
		} else {
			names = varcNames(TOA_MEMBER_NAME_VARC, TOA_PARTY_MAX_SIZE);
		}
		return names.isEmpty() ? null : Party.of(raid, origin, names, revalRoster());
	}

	/**
	 * CoX lists the whole party in the raid side panel. When that widget is not
	 * loaded, the players in the raid instance stand in for it.
	 */
	private List<String> chambersNames() {
		List<String> names = new ArrayList<>();
		Widget list = client.getWidget(InterfaceID.RaidsSidepanel.LIST);
		Widget[] children = list == null ? null : list.getChildren();
		if (children != null) {
			for (Widget child : children) {
				if (child != null) addName(names, child.getName());
			}
		}
		if (!names.isEmpty()) return names;

		WorldView world = client.getTopLevelWorldView();
		if (world != null && world.isInstance()) {
			for (Player player : world.players()) {
				if (player != null) addName(names, player.getName());
			}
		}
		return names;
	}

	private List<String> varcNames(int initialVarcId, int maxSize) {
		List<String> names = new ArrayList<>(maxSize);
		for (int i = 0; i < maxSize; i++) {
			addName(names, client.getVarcStrValue(initialVarcId + i));
		}
		return names;
	}

	/**
	 * Name keys of every Reval member, or null when the loaded clan settings are
	 * not Reval's. Guests are never in the clan settings, so absence from a
	 * loaded roster means guest.
	 */
	private Set<String> revalRoster() {
		if (ClanValidator.isCheckDisabled()) return null;
		ClanSettings settings = client.getClanSettings();
		if (settings == null || !ClanValidator.REQUIRED_CLAN_NAME.equalsIgnoreCase(settings.getName())) return null;
		List<ClanMember> members = settings.getMembers();
		if (members == null || members.isEmpty()) return null;

		Set<String> keys = new HashSet<>();
		for (ClanMember member : members) {
			if (member != null && member.getName() != null) keys.add(nameKey(member.getName()));
		}
		return keys;
	}

	private static void addName(List<String> names, String raw) {
		String name = sanitize(raw);
		if (name.isEmpty()) return;
		for (String existing : names) {
			if (existing.equalsIgnoreCase(name)) return;
		}
		names.add(name);
	}

	private static String sanitize(String raw) {
		if (raw == null || raw.isEmpty()) return "";
		return Text.removeTags(raw).replace(' ', ' ').trim();
	}

	/** RuneScape treats space, underscore and hyphen in a name as the same character. */
	static String nameKey(String name) {
		return sanitize(name).toLowerCase(Locale.ROOT).replaceAll("[ _-]", "");
	}

	/** One raid party: its members in party order and whether each is in Reval. */
	public static final class Party {
		final String raid;
		final Origin origin;
		final List<String> names;
		/** Parallel to names; a null entry means the Reval roster was not loaded. */
		final List<Boolean> revalMembers;

		private Party(String raid, Origin origin, List<String> names, List<Boolean> revalMembers) {
			this.raid = raid;
			this.origin = origin;
			this.names = names;
			this.revalMembers = revalMembers;
		}

		static Party of(String raid, Origin origin, List<String> names, Set<String> revalRoster) {
			List<Boolean> flags = new ArrayList<>(names.size());
			for (String name : names) {
				flags.add(revalRoster == null ? null : revalRoster.contains(nameKey(name)));
			}
			return new Party(raid, origin, names, flags);
		}

		/**
		 * Adds {@code partyMembers} (the names, as the backend has always received
		 * them) and {@code party}: where the party was read and each member's
		 * {@code clanMember} flag, left out when the Reval roster was not loaded.
		 */
		public void addTo(Map<String, Object> data) {
			data.put("partyMembers", names);

			List<Map<String, Object>> members = new ArrayList<>(names.size());
			for (int i = 0; i < names.size(); i++) {
				Map<String, Object> member = new LinkedHashMap<>();
				member.put("name", names.get(i));
				if (revalMembers.get(i) != null) member.put("clanMember", revalMembers.get(i));
				members.add(member);
			}

			Map<String, Object> party = new LinkedHashMap<>();
			party.put("origin", origin == Origin.FINAL_BOSS ? "final_boss" : "live");
			party.put("members", members);
			data.put("party", party);
		}
	}
}

package com.revalclan.util;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemStack;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Collection;
import java.util.Locale;
import java.util.Map;
import java.util.StringJoiner;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Keeps a ToB or ToA reward from being reported again when its chest is reopened.
 *
 * RuneLite's loot tracker reports a raid chest each time it opens after the player
 * has moved between an instance and the normal world (runelite/runelite#18427). A
 * reward opened inside the raid and claimed later from the chest outside it (opposite
 * the Ver Sinhaza bank, or the rewards niche in the ToA lobby), or reopened after a
 * trip through a house, is reported again with whatever is left in it. Until the raid
 * is completed again the chest can only lose items, so a chest holding nothing beyond
 * the reward already reported is that same reward.
 *
 * The reported reward is kept in the RS profile, so a reward left in the chest across
 * a logout or a client restart still counts once. Call on the client thread.
 */
@Singleton
public class RaidRewardLedger {
	private static final String CONFIG_GROUP = "revalclan";
	private static final String CONFIG_KEY_PREFIX = "raidReward_";

	/** "Your completed Tombs of Amascut: Expert Mode count is: 12." — any mode of either raid. */
	private static final Pattern COMPLETION = Pattern.compile(
		"Your completed (Theatre of Blood|Tombs of Amascut)(?::[^:]*)? count is");

	@Inject private ConfigManager configManager;

	/** A completed raid leaves a new reward in its chest: forget the one reported before. */
	public void onGameMessage(String message) {
		String raid = completedRaid(message);
		if (raid != null) {
			configManager.unsetRSProfileConfiguration(CONFIG_GROUP, key(raid));
		}
	}

	/**
	 * Record a loot report. False only for a ToB or ToA chest holding nothing beyond the
	 * reward reported since the raid was last completed; loot from anything else is always
	 * new and is not recorded.
	 */
	public boolean record(String source, Collection<ItemStack> items) {
		String raid = guardedRaid(source);
		if (raid == null) return true;

		Map<Integer, Integer> chest = totals(items);
		if (within(chest, decode(configManager.getRSProfileConfiguration(CONFIG_GROUP, key(raid))))) return false;

		configManager.setRSProfileConfiguration(CONFIG_GROUP, key(raid), encode(chest));
		return true;
	}

	/** The raid a loot source is the reward chest of, when that chest can be reopened outside the raid. */
	static String guardedRaid(String source) {
		String raid = RaidPartyTracker.raidOf(source);
		// Chambers of Xeric has no reward chest outside the raid
		return RaidPartyTracker.CHAMBERS_OF_XERIC.equals(raid) ? null : raid;
	}

	/** The raid a "Your completed ... count is" message completes, or null. */
	static String completedRaid(String message) {
		if (message == null) return null;
		Matcher matcher = COMPLETION.matcher(message);
		return matcher.find() ? matcher.group(1) : null;
	}

	/** Item id → quantity, merging split stacks and skipping empty slots. */
	static Map<Integer, Integer> totals(Collection<ItemStack> items) {
		Map<Integer, Integer> totals = new TreeMap<>();
		for (ItemStack item : items) {
			if (item.getId() > 0 && item.getQuantity() > 0) {
				totals.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return totals;
	}

	/** Whether the reported reward covers every item in the chest, in quantity. */
	static boolean within(Map<Integer, Integer> chest, Map<Integer, Integer> reported) {
		for (Map.Entry<Integer, Integer> item : chest.entrySet()) {
			if (item.getValue() > reported.getOrDefault(item.getKey(), 0)) return false;
		}
		return true;
	}

	/** "id:quantity,id:quantity" in id order. */
	static String encode(Map<Integer, Integer> totals) {
		StringJoiner joined = new StringJoiner(",");
		for (Map.Entry<Integer, Integer> item : new TreeMap<>(totals).entrySet()) {
			joined.add(item.getKey() + ":" + item.getValue());
		}
		return joined.toString();
	}

	/** The totals an encoded reward holds; empty when there is none or it cannot be read. */
	static Map<Integer, Integer> decode(String encoded) {
		Map<Integer, Integer> totals = new TreeMap<>();
		if (encoded == null || encoded.isEmpty()) return totals;
		try {
			for (String entry : encoded.split(",")) {
				int colon = entry.indexOf(':');
				totals.merge(Integer.parseInt(entry.substring(0, colon)), Integer.parseInt(entry.substring(colon + 1)), Integer::sum);
			}
		} catch (RuntimeException e) {
			// Unreadable: report the next chest rather than risk swallowing a new reward
			totals.clear();
		}
		return totals;
	}

	private static String key(String raid) {
		return CONFIG_KEY_PREFIX + raid.toLowerCase(Locale.ROOT).replace(' ', '_');
	}
}

package com.revalclan.util;

import com.revalclan.ui.constants.UIConstants;

import java.awt.Color;
