import com.revalclan.api.leaderboard.LeaderboardResponse;
import com.revalclan.api.points.PointsResponse;
import com.revalclan.api.competitions.*;
import com.revalclan.ui.components.LoginPrompt;
import net.runelite.api.Client;
import org.junit.Before;
import org.junit.Test;
import javax.swing.SwingUtilities;
import java.awt.Component;
import java.awt.Container;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;
import static org.junit.Assert.*;

public class RevalPanelLoadingTest {
	private RevalPanel panel;
	private FakeApi api;
	@Before public void setup() throws Exception {
		SwingUtilities.invokeAndWait(() -> {
			api = new FakeApi();
			Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
				(proxy, method, args) -> method.getName().equals("getAccountHash") ? 42L : null);
			panel = new RevalPanel();
			panel.init(api, client, null, null, null, null, null);
			assertEquals(0, api.count("ranking"));
		});
	}
	@Test public void loginLoadsOnlySelectedMemberTabsOnEdt() throws Exception {
		panel.onLoggedIn(); flush();
		assertEquals(1, api.count("profile"));
		assertEquals(0, api.count("diary"));
		for (String tab : new String[]{"DIARY", "ACHIEVEMENTS", "EVENTS", "COMPETITIONS"}) {
			SwingUtilities.invokeAndWait(() -> { panel.showTab(tab); panel.showTab(tab); });
		}
		assertEquals(2, api.count("events"));
		for (String name : new String[]{"diary", "achievements", "votes", "active", "scheduled"}) assertEquals(name, 1, api.count(name));
	}
	@Test public void publicPanelsSurviveLoginAndLogout() throws Exception {
		SwingUtilities.invokeAndWait(() -> { panel.showTab("LEADERBOARD"); panel.showTab("RANKING"); });
		panel.onLoggedIn(); panel.onLoggedOut(); flush();
		SwingUtilities.invokeAndWait(() -> { panel.showTab("LEADERBOARD"); panel.showTab("RANKING"); });
		assertEquals(1, api.count("leaderboard")); assertEquals(2, api.count("ranking"));
	}
	@Test public void selectionBeforeValidationAndQuickRelogLoadSelectedMemberTab() throws Exception {
		SwingUtilities.invokeAndWait(() -> panel.showTab("DIARY"));
		assertEquals(0, api.count("diary"));
		panel.onLoggedIn(); flush(); assertEquals(1, api.count("diary"));
		panel.onLoggedOut(); panel.onLoggedIn(); flush();
		assertEquals(2, api.count("diary")); assertEquals(0, api.count("events"));
	}
	@Test public void lateCompetitionResponsesCannotReplaceLogoutPrompt() throws Exception {
		panel.onLoggedIn(); flush();
		SwingUtilities.invokeAndWait(() -> panel.showTab("COMPETITIONS"));
		panel.onLoggedOut(); flush();
		api.votes.accept(new VotesResponse()); api.active.accept(new CompetitionsResponse()); api.scheduled.accept(new CompetitionsResponse());
		flush();
		SwingUtilities.invokeAndWait(() -> assertTrue(containsPrompt(panel.getCompetitionsPanel())));
	}
	@Test public void eventsRequireExplicitActionsAndRelogShowsReadyPrompt() throws Exception {
		SwingUtilities.invokeAndWait(() -> panel.showTab("EVENTS"));
		panel.onLoggedIn(); flush();
		assertEquals(0, api.count("events"));
		SwingUtilities.invokeAndWait(() -> assertFalse(containsPrompt(panel.getEventsPanel())));
		SwingUtilities.invokeAndWait(() -> panel.showTab("EVENTS"));
		api.events.accept(new Gson().fromJson("{\"status\":\"success\",\"data\":{\"events\":[{\"name\":\"Past\",\"status\":\"completed\"}]}}", EventsResponse.class));
		flush();
		SwingUtilities.invokeAndWait(() -> panel.showTab("EVENTS"));
		assertEquals(2, api.count("events"));
		panel.onLoggedOut(); panel.onLoggedIn(); flush();
		assertEquals(2, api.count("events"));
		SwingUtilities.invokeAndWait(() -> {
			assertFalse(containsPrompt(panel.getEventsPanel()));
			panel.getEventsPanel().refresh();
		});
		assertEquals(3, api.count("events"));
	}
	private static void flush() throws Exception { SwingUtilities.invokeAndWait(() -> {}); }
	private static boolean containsPrompt(Component c) {
		if (c instanceof LoginPrompt) return true;
		if (c instanceof Container) for (Component child : ((Container)c).getComponents()) if (containsPrompt(child)) return true;
		return false;
	}
	private static class FakeApi extends RevalApiService {
		final Map<String, Integer> calls = new HashMap<>();
		Consumer<VotesResponse> votes;
		Consumer<EventsResponse> events;
		Consumer<CompetitionsResponse> active, scheduled;
		FakeApi() { super(null, new Gson()); }
		void called(String name) { assertTrue("Load must run on EDT", SwingUtilities.isEventDispatchThread()); calls.merge(name, 1, Integer::sum); }
		int count(String name) { return calls.getOrDefault(name, 0); }
		@Override public void fetchPoints(Consumer<PointsResponse> ok, Consumer<Exception> err) { called("ranking"); }
		@Override public void refreshAccount(long hash, Consumer<AccountResponse> ok, Consumer<Exception> err) { called("profile"); }
		@Override public void fetchAccount(long hash, Consumer<AccountResponse> ok, Consumer<Exception> err) { called("profile"); }
		@Override public void fetchLeaderboard(Consumer<LeaderboardResponse> ok, Consumer<Exception> err) { called("leaderboard"); }
		@Override public void fetchDiaries(Long hash, Consumer<DiariesResponse> ok, Consumer<Exception> err) { called("diary"); }
		@Override public void fetchAchievementDefinitions(Long hash, Consumer<AchievementsResponse> ok, Consumer<Exception> err) { called("achievements"); }
		@Override public void fetchEvents(Consumer<EventsResponse> ok, Consumer<Exception> err) { called("events"); events = ok; }
		@Override public void fetchVotes(Consumer<VotesResponse> ok, Consumer<Exception> err) { called("votes"); votes = ok; }
		@Override public void fetchActiveCompetitions(Consumer<CompetitionsResponse> ok, Consumer<Exception> err) { called("active"); active = ok; }
		@Override public void fetchScheduledCompetitions(Consumer<CompetitionsResponse> ok, Consumer<Exception> err) { called("scheduled"); scheduled = ok; }
	}
}

package com.revalclan.util;

import com.google.gson.Gson;
import com.revalclan.RevalClanConfig;
import com.revalclan.api.RevalApiService;
import com.revalclan.api.announcements.AnnouncementsResponse;
import com.revalclan.api.notifications.NotificationsResponse;
import net.runelite.api.Client;
import org.junit.Test;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import static org.junit.Assert.*;

public class AnnouncementPollingTest {
	@Test public void pollsHourlyAndIgnoresPreviousLoginResponses() throws Exception {
		AnnouncementService service = new AnnouncementService();
		FakeApi api = new FakeApi();
		inject(service, "revalApiService", api);
		inject(service, "client", Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) -> 42L));
		inject(service, "config", Proxy.newProxyInstance(RevalClanConfig.class.getClassLoader(), new Class<?>[]{RevalClanConfig.class},
			(proxy, method, args) -> true));
		ticks(service, 4); assertEquals(0, api.responses.size());
		ticks(service, 1); assertEquals(1, api.responses.size());
		NotificationsResponse empty = new Gson().fromJson("{\"status\":\"success\",\"data\":{\"notifications\":[]}}", NotificationsResponse.class);
		api.responses.get(0).accept(empty);
		// No marker was acknowledged, so a heartbeat retries; matching successful versions do not.
		service.onServerVersion("v1"); assertEquals(2, api.responses.size());
		NotificationsResponse versioned = new Gson().fromJson("{\"status\":\"success\",\"data\":{\"version\":\"v1\",\"notifications\":[]}}", NotificationsResponse.class);
		api.responses.get(1).accept(versioned);
		service.onServerVersion("v1"); assertEquals(2, api.responses.size());
		service.onServerVersion("v2"); assertEquals(3, api.responses.size());
		api.errors.get(2).accept(new Exception("retry"));
		service.onServerVersion("v2"); assertEquals(4, api.responses.size());
		api.responses.get(3).accept(versioned);
		api.responses.clear(); api.errors.clear();
		// Reset counts only; the service still has a successful fetch and a full hourly timeout.

		ticks(service, 5999); assertEquals(0, api.responses.size());
		ticks(service, 1); assertEquals(1, api.responses.size());
		ticks(service, 7000); assertEquals(1, api.responses.size()); // No overlapping request.
		service.reset(); ticks(service, 5); assertEquals(2, api.responses.size());
		api.responses.get(0).accept(empty); // Old callback must not complete the new request.
		ticks(service, 7000); assertEquals(2, api.responses.size());
		api.errors.get(1).accept(new Exception("Unavailable"));
		ticks(service, 99); assertEquals(2, api.responses.size());
		ticks(service, 1); assertEquals(3, api.responses.size());
	}
	private static void ticks(AnnouncementService service, int count) { for (int i = 0; i < count; i++) service.onGameTick(); }
	private static void inject(Object target, String name, Object value) throws Exception {
		Field field = target.getClass().getDeclaredField(name);
		field.setAccessible(true); field.set(target, value);
	}
	private static class FakeApi extends RevalApiService {
		final List<Consumer<NotificationsResponse>> responses = new ArrayList<>();
		final List<Consumer<Exception>> errors = new ArrayList<>();
		FakeApi() { super(null, new Gson()); }
		@Override public void fetchAnnouncements(Consumer<AnnouncementsResponse> ok, Consumer<Exception> error) {}
		@Override public void fetchNotifications(long account, Consumer<NotificationsResponse> ok, Consumer<Exception> error) {
			responses.add(ok); errors.add(error);
		}
	}
}

package com.revalclan.util;

import com.google.gson.Gson;
import okhttp3.*;
import org.junit.Test;
import java.io.IOException;
import java.lang.reflect.Field;
import java.util.concurrent.*;
import static org.junit.Assert.*;

public class EventFilterRefreshTest {
	@Test public void versionsDailyFallbackRetriesAndRelogUseOnlySuccessfullyAppliedFilters() throws Exception {
		BlockingQueue<Pending> requests = new LinkedBlockingQueue<>();
		OkHttpClient http = new OkHttpClient() {
			@Override public Call newCall(Request request) {
				Pending pending = new Pending(request);
				return new Call() {
					public Request request() { return request; }
					public Response execute() { throw new UnsupportedOperationException(); }
					public void enqueue(Callback callback) { pending.callback = callback; requests.add(pending); }
					public void cancel() {}
					public boolean isExecuted() { return pending.callback != null; }
					public boolean isCanceled() { return false; }
					public okio.Timeout timeout() { return okio.Timeout.NONE; }
					public Call clone() { return newCall(request); }
				};
			}
		};
		try {
			EventFilterManager filters = new EventFilterManager();
			inject(filters, "httpClient", http); inject(filters, "gson", new Gson());
			filters.setOnFiltersApplied(() -> assertFalse("Listener must run outside the manager lock", Thread.holdsLock(filters)));
			filters.resetSession(); filters.onGameTick();
			Pending first = take(requests);
			filters.onServerVersion("v1"); assertTrue(requests.isEmpty());
			first.complete(200, "v1", 111);
			assertTrue(filters.getFilters().getLootWhitelist().contains(111));
			filters.onServerVersion("v1");
			for (int i = 0; i < 143999; i++) filters.onGameTick();
			assertTrue(requests.isEmpty());
			filters.onGameTick();
			take(requests).complete(500, null, 0);
			for (int i = 0; i < 99; i++) filters.onGameTick();
			assertTrue(requests.isEmpty());
			filters.onGameTick();
			Pending old = take(requests);
			filters.resetSession(); filters.onGameTick();
			Pending current = take(requests);
			old.complete(200, "stale", 999);
			assertFalse(filters.getFilters().getLootWhitelist().contains(999));
			current.complete(200, "v2", 222);
			filters.onServerVersion("v2"); assertTrue(requests.isEmpty());
			filters.onServerVersion("v3");
			take(requests).complete(200, "v3", 333);
			assertTrue(filters.getFilters().getLootWhitelist().contains(333));
			filters.onServerVersion(null);
			take(requests).complete(200, null, 444);
			for (int i = 0; i < 1000; i++) filters.onGameTick();
			assertTrue("No separate legacy timer", requests.isEmpty());
		} finally {
			http.dispatcher().executorService().shutdownNow();
			http.connectionPool().evictAll();
		}
	}
	private static <T> T take(BlockingQueue<T> queue) throws Exception {
		T value = queue.poll(5, TimeUnit.SECONDS);
		assertNotNull("Expected HTTP activity", value);
		return value;
	}
	private static void inject(Object target, String name, Object value) throws Exception {
		Field field = target.getClass().getDeclaredField(name);
		field.setAccessible(true); field.set(target, value);
	}
	private static class Pending {
		final Request request;
		Callback callback;
		Pending(Request request) { this.request = request; }
		void complete(int status, String version, int item) throws IOException {
			Response.Builder builder = new Response.Builder().request(request).protocol(Protocol.HTTP_1_1)
				.code(status).message("test").body(ResponseBody.create(MediaType.parse("application/json"),
					"{\"loot\":{\"whitelist\":[" + item + "]}}"));
			if (version != null) builder.header("X-Reval-Filters-Version", version);
			callback.onResponse(null, builder.build());
		}
	}
}

package com.revalclan.util;

import com.revalclan.util.RaidPartyTracker.Origin;
import com.revalclan.util.RaidPartyTracker.Party;
import org.junit.Test;

import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import static com.revalclan.util.RaidPartyTracker.CHAMBERS_OF_XERIC;
import static com.revalclan.util.RaidPartyTracker.SAVED_PARTY_TTL_MS;
import static com.revalclan.util.RaidPartyTracker.THEATRE_OF_BLOOD;
import static com.revalclan.util.RaidPartyTracker.TOMBS_OF_AMASCUT;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class RaidPartyTrackerTest {
	private static Party party(String raid, Origin origin, String... names) {
		return Party.of(raid, origin, Arrays.asList(names), null);
	}

	@Test
	public void raidSourcesIgnoreTheModeSuffix() {
		assertEquals(THEATRE_OF_BLOOD, RaidPartyTracker.raidOf("Theatre of Blood: Hard Mode"));
		assertEquals(CHAMBERS_OF_XERIC, RaidPartyTracker.raidOf("Chambers of Xeric Challenge Mode"));
		assertEquals(TOMBS_OF_AMASCUT, RaidPartyTracker.raidOf("Tombs of Amascut: Expert Mode"));
		assertNull(RaidPartyTracker.raidOf("Zulrah"));
		assertNull(RaidPartyTracker.raidOf(null));
	}

	@Test
	public void onlyTheLastBossOfEachRaidSavesTheParty() {
		assertEquals(CHAMBERS_OF_XERIC, RaidPartyTracker.raidForFinalBoss("Great Olm"));
		assertEquals(THEATRE_OF_BLOOD, RaidPartyTracker.raidForFinalBoss("Verzik Vitur"));
		assertEquals(TOMBS_OF_AMASCUT, RaidPartyTracker.raidForFinalBoss("Tumeken's Warden"));
		assertEquals(TOMBS_OF_AMASCUT, RaidPartyTracker.raidForFinalBoss("Elidinis’ Warden"));
		assertNull(RaidPartyTracker.raidForFinalBoss("Great Olm Left Claw"));
		assertNull(RaidPartyTracker.raidForFinalBoss("The Maiden of Sugadinti"));
		assertNull(RaidPartyTracker.raidForFinalBoss(null));
	}

	@Test
	public void insideTheRaidTheLivePartyWins() {
		Party live = party(THEATRE_OF_BLOOD, Origin.LIVE, "A", "B");
		Party saved = party(THEATRE_OF_BLOOD, Origin.FINAL_BOSS, "A", "B", "C");
		assertSame(live, RaidPartyTracker.choose(THEATRE_OF_BLOOD, live, true, saved, 1_000));
	}

	@Test
	public void outsideTheRaidTheSavedPartyWins() {
		Party live = party(TOMBS_OF_AMASCUT, Origin.LIVE, "A");
		Party saved = party(TOMBS_OF_AMASCUT, Origin.FINAL_BOSS, "A", "B");
		assertSame(saved, RaidPartyTracker.choose(TOMBS_OF_AMASCUT, live, false, saved, 60_000));
		assertSame(saved, RaidPartyTracker.choose(TOMBS_OF_AMASCUT, null, false, saved, 60_000));
	}

	@Test
	public void aSavedPartyFromAnotherRaidOrPastItsTtlIsIgnored() {
		Party live = party(TOMBS_OF_AMASCUT, Origin.LIVE, "A");
		Party otherRaid = party(THEATRE_OF_BLOOD, Origin.FINAL_BOSS, "B");
		Party stale = party(TOMBS_OF_AMASCUT, Origin.FINAL_BOSS, "C");
		assertSame(live, RaidPartyTracker.choose(TOMBS_OF_AMASCUT, live, false, otherRaid, 1_000));
		assertSame(live, RaidPartyTracker.choose(TOMBS_OF_AMASCUT, live, false, stale, SAVED_PARTY_TTL_MS + 1));
		assertNull(RaidPartyTracker.choose(TOMBS_OF_AMASCUT, null, false, stale, SAVED_PARTY_TTL_MS + 1));
	}

	@Test
	public void membersAreFlaggedAgainstTheRevalRoster() {
		Set<String> roster = new HashSet<>(Arrays.asList(
			RaidPartyTracker.nameKey("Iron Man"), RaidPartyTracker.nameKey("Zezima")));
		Party party = Party.of(CHAMBERS_OF_XERIC, Origin.LIVE, Arrays.asList("iron_man", "Zezima", "Guest"), roster);

		Map<String, Object> data = new HashMap<>();
		party.addTo(data);

		assertEquals(Arrays.asList("iron_man", "Zezima", "Guest"), data.get("partyMembers"));
		Map<?, ?> payload = (Map<?, ?>) data.get("party");
		assertEquals("live", payload.get("origin"));
		List<?> members = (List<?>) payload.get("members");
		assertEquals(true, ((Map<?, ?>) members.get(0)).get("clanMember"));
		assertEquals(true, ((Map<?, ?>) members.get(1)).get("clanMember"));
		assertEquals(false, ((Map<?, ?>) members.get(2)).get("clanMember"));
	}

	@Test
	public void withoutARosterTheFlagIsLeftOut() {
		Map<String, Object> data = new HashMap<>();
		party(THEATRE_OF_BLOOD, Origin.FINAL_BOSS, "A").addTo(data);

		Map<?, ?> payload = (Map<?, ?>) data.get("party");
		assertEquals("final_boss", payload.get("origin"));
		Map<?, ?> member = (Map<?, ?>) ((List<?>) payload.get("members")).get(0);
		assertEquals("A", member.get("name"));
		assertFalse(member.containsKey("clanMember"));
	}
}

package com.revalclan.util;

import net.runelite.client.game.ItemStack;
import org.junit.Test;

import java.util.Arrays;
import java.util.Map;

import static com.revalclan.util.RaidPartyTracker.THEATRE_OF_BLOOD;
import static com.revalclan.util.RaidPartyTracker.TOMBS_OF_AMASCUT;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class RaidRewardLedgerTest {
	private static final int FANG = 26219;
	private static final int LIGHTBEARER = 25975;
	private static final int DEATH_RUNE = 560;

	private static Map<Integer, Integer> chest(ItemStack... items) {
		return RaidRewardLedger.totals(Arrays.asList(items));
	}

	@Test
	public void aReopenedChestHoldsNothingBeyondTheReportedReward() {
		Map<Integer, Integer> reported = chest(new ItemStack(FANG, 1), new ItemStack(DEATH_RUNE, 300));

		assertTrue(RaidRewardLedger.within(chest(new ItemStack(DEATH_RUNE, 300), new ItemStack(FANG, 1)), reported));
		// Partly claimed before the chest was reopened
		assertTrue(RaidRewardLedger.within(chest(new ItemStack(DEATH_RUNE, 120)), reported));
		assertTrue(RaidRewardLedger.within(chest(), reported));
	}

	@Test
	public void aChestHoldingAnythingMoreIsANewReward() {
		Map<Integer, Integer> reported = chest(new ItemStack(FANG, 1), new ItemStack(DEATH_RUNE, 300));

		assertFalse(RaidRewardLedger.within(chest(new ItemStack(LIGHTBEARER, 1)), reported));
		assertFalse(RaidRewardLedger.within(chest(new ItemStack(DEATH_RUNE, 301)), reported));
		assertFalse(RaidRewardLedger.within(chest(new ItemStack(FANG, 1)), chest()));
	}

	@Test
	public void totalsMergeSplitStacksAndSkipEmptySlots() {
		Map<Integer, Integer> totals = chest(new ItemStack(DEATH_RUNE, 100), new ItemStack(-1, 0), new ItemStack(DEATH_RUNE, 50));

		assertEquals(1, totals.size());
		assertEquals(Integer.valueOf(150), totals.get(DEATH_RUNE));
	}

	@Test
	public void theRecordRoundTripsAndAnUnreadableOneIsEmpty() {
		Map<Integer, Integer> reward = chest(new ItemStack(FANG, 1), new ItemStack(DEATH_RUNE, 300));

		assertEquals("560:300,26219:1", RaidRewardLedger.encode(reward));
		assertEquals(reward, RaidRewardLedger.decode(RaidRewardLedger.encode(reward)));
		assertTrue(RaidRewardLedger.decode(null).isEmpty());
		assertTrue(RaidRewardLedger.decode("").isEmpty());
		assertTrue(RaidRewardLedger.decode("560:300,oops").isEmpty());
	}

	@Test
	public void everyModeOfBothRaidsCompletesItsRaid() {
		assertEquals(THEATRE_OF_BLOOD, RaidRewardLedger.completedRaid("Your completed Theatre of Blood count is: 12."));
		assertEquals(THEATRE_OF_BLOOD, RaidRewardLedger.completedRaid("Your completed Theatre of Blood: Hard Mode count is: 3."));
		assertEquals(TOMBS_OF_AMASCUT, RaidRewardLedger.completedRaid("Your completed Tombs of Amascut: Entry Mode count is: 7."));
		assertEquals(TOMBS_OF_AMASCUT, RaidRewardLedger.completedRaid("Your completed Tombs of Amascut: Expert Mode count is: 1,204."));
	}

	@Test
	public void otherCountsCompleteNothing() {
		assertNull(RaidRewardLedger.completedRaid("Your completed Chambers of Xeric count is: 40."));
		assertNull(RaidRewardLedger.completedRaid("Your Vorkath kill count is: 5."));
		assertNull(RaidRewardLedger.completedRaid(null));
	}

	@Test
	public void onlyTobAndToaChestsAreGuarded() {
		assertEquals(THEATRE_OF_BLOOD, RaidRewardLedger.guardedRaid("Theatre of Blood"));
		assertEquals(TOMBS_OF_AMASCUT, RaidRewardLedger.guardedRaid("Tombs of Amascut"));
		assertNull(RaidRewardLedger.guardedRaid("Chambers of Xeric"));
		assertNull(RaidRewardLedger.guardedRaid("Barrows"));
		assertNull(RaidRewardLedger.guardedRaid(null));
	}
}
